function mergeDeep(base, extra){if(!extra||typeof extra!=='object')return base;for(const k of Object.keys(extra)){if(extra[k]&&typeof extra[k]==='object'&&!Array.isArray(extra[k])&&base[k]&&typeof base[k]==='object'&&!Array.isArray(base[k]))mergeDeep(base[k],extra[k]);else base[k]=extra[k]}return base}
function loadState(){try{const raw=localStorage.getItem(APP_KEY);return raw?mergeDeep(defaultState(),JSON.parse(raw)):defaultState()}catch(e){return defaultState()}}
function saveState(msg=true){state.updatedAt=new Date().toISOString();try{localStorage.setItem(APP_KEY,JSON.stringify(state));if(msg)toast('✓ Tersimpan di perangkat ini');return true}catch(e){if(msg)toast('⚠ Penyimpanan browser gagal. Data tetap tersedia selama sesi ini.');return false}}
function toast(message){const el=document.getElementById('toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2700)}
function esc(s=''){return String(s).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function deepClone(x){return JSON.parse(JSON.stringify(x))}
function routeKey(r=route){return r.name+JSON.stringify(r.params||{})}
