function navigate(name,params={}){if(state.onboarding.completed && !['guide','opening','identity','aperception'].includes(name))state.ui.lastRoute=name;route={name,params};window.scrollTo({top:0,behavior:'smooth'});render()}
function home(){navigate('dashboard')}
