function goBackFromHelp(){navigate(state.ui.lastRoute||'dashboard')}
function openUnavailable(message){toast(message)}
function header(){if(!state.onboarding.completed)return '';const visited=Object.values(state.labs).filter(x=>x.visited).length;const passed=Object.values(state.labs).filter(x=>x.checkpoint.status==='benar').length;return `<header class="topbar"><div class="brand"><div style="width:44px;height:44px;border-radius:14px;background:#123b4a;display:grid;place-items:center;color:#70e7f5">${ICONS.sim}</div><div><strong>Kidney Lab</strong><span>${esc(state.student.name||'Siswa')} · ${esc(state.student.className||'Kelas VIII')}</span></div></div><button class="navbtn" onclick="home()">${ICONS.home} Home</button><button class="navbtn" onclick="navigate('materialHub')">${ICONS.material} Materi</button><button class="navbtn" onclick="navigate('simulation')">${ICONS.sim} Simulasi</button><button class="navbtn" onclick="help()">${ICONS.help} Petunjuk</button><span class="storage hide-mobile">Materi ${visited}/4 · Checkpoint ${passed}/4</span></header>`}
function setApp(html){document.getElementById('app').innerHTML=header()+`<main class="shell screen">${html}</main>`}
function imgFigure(src,alt,caption='',cls=''){return `<figure class="figure ${cls}"><img loading="lazy" src="${src}" alt="${esc(alt)}" onerror="this.style.display='none';this.nextElementSibling.style.display='flex'"><div class="fallback">⚠ Gambar tidak dapat dimuat.<br><strong>${esc(alt)}</strong></div>${caption?`<figcaption>${caption}</figcaption>`:''}</figure>`}
function labStatus(lab){const c=lab.checkpoint.status;if(c==='benar')return ['✓ Selesai','good'];if(c==='salah_perlu_baca_ulang')return ['↻ Perlu ulang','bad'];if(c==='siap_coba_lagi')return ['↻ Siap coba lagi','warn'];if(lab.visited)return ['▶ Sedang dipelajari','cyan'];return ['○ Belum dipelajari','']}
function progressPct(){const vals=Object.values(state.labs);const visited=vals.filter(l=>l.visited).length;const passed=vals.filter(l=>l.checkpoint.status==='benar').length;return Math.round(((visited+passed)/(8))*100)}
