const LAB_SOURCE_NOTES={"l1-fakta":"NIDDK/NCBI: ukuran ginjal, ±1 juta nefron, aliran darah ginjal besar; ±180 L filtrat dan ±1–2 L urin adalah angka ilustratif dewasa.","l1-mengatur":"NIDDK: ginjal membantu mengatur tekanan darah, pembentukan sel darah merah, dan kesehatan tulang; fisiologi dasar untuk asam-basa.","l2-angka":"Fisiologi ginjal: GFR sekitar 120–125 mL/menit dan fraksi filtrasi sekitar 20% pada ilustrasi dewasa.","l2-autoregulasi":"Fisiologi ginjal: autoregulasi miogenik dan tubuloglomerular mempertahankan GFR dalam rentang tekanan tertentu.","l3-glukosa":"NIDDK: kriteria glukosa puasa normal ≤99 mg/dL dan 2-jam OGTT ≤139 mg/dL. Ambang ginjal ±180 mg/dL adalah asumsi model simulasi, bukan batas diagnosis.","l4-isk":"NIDDK: gejala ISK, infeksi kandung kemih lebih sering pada perempuan karena anatomi uretra, dan pentingnya evaluasi bila ada gejala.","l4-hipertensi-diabetes":"WHO/Kemenkes/NIDDK: diabetes dan hipertensi merupakan faktor penting/penyebab umum penyakit ginjal kronis; hipertensi sering tanpa gejala.","l4-dialisis-transplantasi":"NIDDK: hemodialisis, dialisis peritoneal, transplantasi, dan manajemen konservatif sebagai pilihan pada gagal ginjal.","l4-hidrasi":"NIDDK: kebutuhan cairan berbeda; urin pucat dapat menjadi petunjuk umum, dan sebagian gagal ginjal/jantung memerlukan pembatasan cairan."};
