 {id:'air',name:'Air',img:'game_air.webp',correct:'filtrat'}, {id:'urea',name:'Urea',img:'game_urea.webp',correct:'filtrat'}, {id:'glukosa',name:'Glukosa',img:'game_glukosa.webp',correct:'filtrat'}, {id:'ion',name:'Ion',img:'game_ion.webp',correct:'filtrat'}, {id:'eritrosit',name:'Sel darah merah',img:'game_sel_darah_merah.webp',correct:'darah'}, {id:'protein',name:'Protein besar',img:'game_protein_besar.webp',correct:'darah'}
