function render(){switch(route.name){case'opening':renderOpening();break;case'identity':renderIdentity();break;case'guide':renderGuide();break;case'aperception':renderAperception();break;case'dashboard':renderDashboard();break;case'objectives':renderObjectives();break;case'materialHub':renderMaterialHub();break;case'lab':renderLab(route.params.lab,route.params.slide??0);break;case'checkpoint':renderCheckpoint(route.params.lab);break;case'simulation':renderSimulation();break;case'game':renderGame();break;case'evaluation':renderEvaluation();break;case'results':renderResults();break;case'reflection':renderReflection();break;case'assets':renderAssets();break;default:renderDashboard()}}
function renderOpening(){setApp(`<section class="hero"><div class="hero-copy"><div class="eyebrow">IPA · SMP Kelas VIII · Kurikulum Merdeka</div><h1>NEFI’S<br>KIDNEY LAB</h1><p class="lead">Laboratorium Penyaring Tubuh — pelajari anatomi ginjal dan nefron dengan visual ilmiah, lalu jalankan simulasi interaktif pembentukan urin.</p><div class="mascot-welcome"><img class="mascot-img" src="${MASCOT_ASSETS.waving}" alt="Nefi, maskot ginjal, melambaikan tangan"><div><strong>Hai! Aku Nefi.</strong><p>Aku akan menemanimu mengamati, mencoba simulasi, dan mengecek pemahaman tentang ginjal.</p></div></div><div class="actions"><button class="btn primary" onclick="navigate('identity')">Masuk Lab →</button></div><p class="hint">Dirancang untuk IFP, laptop, dan HP · 3 JP · data belajar disimpan lokal di browser ini.</p></div><div class="hero-visual"><img src="${ASSETS.external.niddk_urinary_tract}" alt="Ilustrasi ilmiah sistem urin manusia, ginjal, ureter, kandung kemih, dan nefron dari NIDDK/NIH" style="background:white;border-radius:22px;padding:8px"></div></section>`)}
function renderIdentity(){setApp(`<section class="panel" style="max-width:900px;margin:5vh auto"><div class="pagehead"><div><div class="eyebrow">Identitas</div><h1>Siapa ilmuwan muda hari ini?</h1><p>Isi nama panggilan dan kelasmu. Identitas serta progres hanya disimpan di browser pada perangkat ini.</p></div></div><div class="formgrid"><div class="field"><label for="name">Nama</label><input id="name" autocomplete="name" placeholder="Contoh: Alya" value="${esc(state.student.name)}"></div><div class="field"><label for="className">Kelas</label><input id="className" placeholder="Contoh: VIII B" value="${esc(state.student.className)}"></div></div><div class="actions split"><button class="btn ghost" onclick="navigate('opening')">← Kembali</button><button class="btn primary" onclick="submitIdentity()">Lanjut ke Panduan →</button></div></section>`)}
function submitIdentity(){const name=document.getElementById('name').value.trim(),cl=document.getElementById('className').value.trim();if(!name||!cl){toast('Nama dan kelas perlu diisi terlebih dahulu.');return}state.student={name,className:cl};saveState(false);navigate('guide',{onboarding:true})}
function renderGuide(){const onboarding=!state.onboarding.completed;setApp(`<section><div class="pagehead"><div><div class="eyebrow">Panduan & Alur</div><h1>Cara menggunakan Kidney Lab</h1><p>Mode proyek ini adalah <strong>Bebas</strong>: seluruh materi, game, refleksi, dan Evaluasi dapat dibuka sejak Dashboard. Cek Pemahaman tetap menjadi latihan formatif dan tidak mengunci menu lain.</p></div></div><div class="guide-grid">
${guideCard(1,'Dashboard','Home/Menu Utama adalah pusat navigasi. Semua kartu utama selalu terlihat. Lihat Hasil baru tersedia setelah Evaluasi dikirim.')}
${guideCard(2,'Status materi','○ Belum Dipelajari · ▶ Sedang Dipelajari · ↻ Perlu Ulang · ✓ Selesai. Karena mode Bebas, status hanya penanda progres, bukan gembok.')}
${guideCard(3,'Cek Pemahaman','Setiap Lab memiliki checkpoint. Jika belum tepat, kamu mendapat petunjuk dan harus membuka kembali materi Lab tersebut sebelum retry aktif.')}
${guideCard(4,'Navigasi','Home kembali ke Dashboard tanpa mereset progres. Kembali ke Hub memilih Lab lain. Lanjut/Sebelumnya berpindah layar materi. Petunjuk dapat dibuka kapan saja.')}
${guideCard(5,'Simulasi & Mini Game','Simulasi memperlihatkan filtrasi, reabsorpsi, sekresi, dan urin akhir pada model nefron. Game Drag & Drop adalah latihan; skor game terpisah dari Nilai Evaluasi.')}
${guideCard(6,'Evaluasi & gembok','Evaluasi aktif sejak awal karena mode Bebas. Ikon gembok hanya dipakai pada kartu Lihat Hasil sebelum Evaluasi selesai; setelah submit, laporan hasil menjadi aktif.')}
</div><div class="actions split"><button class="btn ghost" onclick="${onboarding?"navigate('identity')":"goBackFromHelp()"}">← ${onboarding?'Kembali':'Kembali ke Aktivitas'}</button><button class="btn primary" onclick="${onboarding?'finishGuide()':'goBackFromHelp()'}">${onboarding?'Mulai Belajar →':'Tutup Petunjuk'}</button></div></section>`)}
function guideCard(n,t,b){return `<article class="card guide-card"><div class="num">${n}</div><h2>${t}</h2><p>${b}</p></article>`}
function finishGuide(){state.onboarding.guideViewed=true;saveState(false);navigate('aperception')}
function renderAperception(){setApp(`<section><div class="pagehead"><div><div class="eyebrow">Apersepsi Kontekstual</div><h1>Setelah berkeringat, mengapa urin bisa berubah?</h1><p>Gunakan model konseptual berikut. Ini bukan alat diagnosis; tujuan utamanya menghubungkan keseimbangan air tubuh dengan kerja ginjal.</p></div></div><div class="model-samples"><article class="model-sample"><div class="droplet small"></div><h2>Setelah aktivitas & banyak berkeringat</h2><p class="muted">Tubuh kehilangan lebih banyak air → ginjal membantu mempertahankan air → volume urin dapat lebih sedikit dan lebih pekat.</p></article><article class="model-sample"><div class="droplet light"></div><h2>Setelah memperoleh cukup cairan</h2><p class="muted">Ketersediaan air lebih tinggi → tubuh tidak perlu mempertahankan air sebanyak kondisi sebelumnya → volume urin dapat lebih banyak dan lebih encer.</p></article></div><section class="panel" style="margin-top:18px"><h2>Pertanyaan pemantik</h2><div class="field"><label>1. Mengapa jumlah dan kepekatan urin tidak selalu sama?</label><div class="choice-list" id="apChoices">${['Ginjal dapat menyesuaikan banyaknya air yang dipertahankan tubuh','Ginjal berhenti bekerja ketika kita berkeringat','Semua cairan yang diminum langsung menjadi urin','Saya belum yakin'].map(x=>`<label class="choice"><input type="radio" name="ap" value="${esc(x)}" ${state.onboarding.hydrationGuess===x?'checked':''}><span>${x}</span></label>`).join('')}</div></div><div class="field"><label for="hypothesis">2. Hipotesisku: jika ginjal menyaring darah, mengapa sel darah dan protein besar biasanya tidak ikut keluar bersama urin?</label><textarea id="hypothesis" maxlength="220" placeholder="Tulis dugaanmu dalam 1–2 kalimat…">${esc(state.onboarding.hypothesis)}</textarea></div><div class="callout">Belum ada skor. Simpan dugaanmu; nanti bandingkan dengan anatomi NIDDK/NIH dan simulasi nefron.</div><div class="actions split"><button class="btn ghost" onclick="navigate('guide',{onboarding:true})">← Panduan</button><button class="btn primary" onclick="finishAperception()">Masuk Dashboard →</button></div></section></section>`)}
function finishAperception(){const g=document.querySelector('input[name="ap"]:checked');state.onboarding.hydrationGuess=g?g.value:'Saya belum yakin';state.onboarding.hypothesis=document.getElementById('hypothesis').value.trim();state.onboarding.aperceptionCompleted=true;state.onboarding.completed=true;saveState(false);navigate('dashboard');toast('Dugaan awal tersimpan. Mari mengujinya di Kidney Lab!')}
function renderDashboard(){const visited=Object.values(state.labs).filter(x=>x.visited).length,passed=Object.values(state.labs).filter(x=>x.checkpoint.status==='benar').length;const resultReady=state.evaluation.submitted;setApp(`<section><div class="pagehead"><div><div class="eyebrow">Menu Utama / Dashboard</div><h1>Selamat datang, ${esc(state.student.name)}.</h1><p>Semua aktivitas belajar dapat dipilih sejak awal. Progress adalah penanda, bukan pengunci.</p></div><div class="mascot-head"><img class="mascot-img" src="${MASCOT_ASSETS.thumbs}" alt="Nefi memberi semangat dengan jempol"><span class="badge cyan">Mode Bebas</span></div></div><div class="panel" style="margin-bottom:18px"><div class="statusline"><strong>Progress belajar</strong><span>Lab dikunjungi ${visited}/4</span><span>Checkpoint lulus ${passed}/4</span><span>Evaluasi ${state.evaluation.submitted?'selesai':'belum disubmit'}</span></div><div class="progressbar"><span style="width:${progressPct()}%"></span></div></div><div class="dash-grid">
${dashCard(ICONS.target,'Tujuan Pembelajaran','Lihat target kemampuan dan kriteria ketercapaian.','Terbuka',"navigate('objectives')")}
${dashCard(ICONS.material,'Materi Pembelajaran','Buka HUB empat stasiun dengan gambar anatomi ilmiah NIDDK/NIH dan sumber kesehatan Indonesia.',`Lab dikunjungi ${visited}/4`,"navigate('materialHub')")}
${dashCard(ICONS.sim,'Simulasi Pembentukan Urin','Jalankan simulasi interaktif filtrasi → reabsorpsi → sekresi → urin akhir pada model nefron.',state.simulation.lastRun?'Sudah dijalankan':'Siap digunakan',"navigate('simulation')")}
${dashCard(ICONS.game,'Mini Game','Drag & Drop “Sortir Filtrat”. Skor latihan terpisah dari Evaluasi.',state.game.played?`Skor ${state.game.score}`:'Belum dimainkan',"navigate('game')")}
${dashCard(ICONS.eval,'Evaluasi','15 soal kognitif multi-tipe. Aktif sejak awal pada mode Bebas.',state.evaluation.submitted?`Sudah selesai · ${state.evaluation.finalScore}`:'Siap dikerjakan',"navigate('evaluation')")}
${dashCard(ICONS.result,'Lihat Hasil','Nilai akhir, kategori, bagian perlu penguatan, saran, dan refleksi.',resultReady?'Hasil tersedia':'🔒 Selesaikan Evaluasi terlebih dahulu',resultReady?"navigate('results')":"openUnavailable('Lihat Hasil tersedia setelah Evaluasi dikirim.')",!resultReady)}
${dashCard(ICONS.reflect,'Refleksi','Catat yang sudah dipahami, yang masih sulit, dan rencana agar lebih paham.',state.reflection.understood?'Tersimpan':'Dapat diisi kapan saja',"navigate('reflection')")}
${dashCard(ICONS.help,'Petunjuk','Buka kembali panduan penggunaan tanpa kehilangan posisi belajar.','Selalu tersedia',"help()")}
</div></section>`)}
function dashCard(icon,title,desc,status,action,locked=false){return `<article class="card dashboard-card ${locked?'locked':''}"><div class="card-icon">${icon}</div><h2>${title}</h2><p class="grow">${desc}</p><span class="badge ${locked?'warn':'cyan'}">${status}</span><button class="btn ${locked?'warn':'primary'}" onclick="${action}">${locked?'Lihat Syarat':'Buka'}</button></article>`}
function renderObjectives(){setApp(`<section><div class="pagehead"><div><div class="eyebrow">Tujuan Pembelajaran Final</div><h1>Target Eksperimen</h1><p>Pembelajaran mendalam bergerak dari memahami konsep, mengaplikasikan penalaran, hingga merefleksikan cara belajar. Dimensi yang didukung: Penalaran Kritis, Kesehatan, Kemandirian, dan Komunikasi.</p></div></div><div class="target-grid">${TP.map((t,i)=>`<article class="card"><span class="badge cyan">TP ${i+1}</span><h2 style="margin-top:12px">Saya bisa…</h2><p>${t}</p></article>`).join('')}</div><section class="panel" style="margin-top:18px"><h2>Kriteria ketercapaian</h2><p class="content-text">Murid mampu menghubungkan struktur–fungsi ginjal, menjelaskan filtrasi–reabsorpsi–sekresi secara runtut, menggunakan sebab–akibat pada kasus/data sederhana, membedakan gangguan utama secara konseptual, dan memilih tindakan menjaga kesehatan ginjal berdasarkan informasi tepercaya.</p><div class="actions"><button class="btn" onclick="home()">⌂ Menu Utama</button><button class="btn primary" onclick="navigate('materialHub')">Pilih Stasiun →</button></div></section></section>`)}
const labNavRuntime={returnToLab:null};
const labUiRuntime={steps:{}};
function labEnsureProgress(labId,st=state){const L=st.labs?.[labId];if(!L)return;L.visitedSlideIds=Array.isArray(L.visitedSlideIds)?L.visitedSlideIds:[];if(!L.visitedSlideIds.length&&Array.isArray(L.visitedSlides)){const old=LAB_OLD_SLIDE_IDS[labId]||[];for(const idx of L.visitedSlides){const id=old[Number(idx)];if(id&&!L.visitedSlideIds.includes(id))L.visitedSlideIds.push(id)}}}
function labSlideIndex(labId,slideId){const lab=LABS[labId];if(!lab)return -1;return lab.slides.findIndex(x=>x.id===slideId)}
function labGo(labId,slideId,returnTo=''){const idx=labSlideIndex(labId,slideId);if(idx<0){toast('Materi tujuan tidak ditemukan.');return}navigate('lab',{lab:labId,slide:idx,returnTo:returnTo||''})}
function labNav(labId,idx){navigate('lab',{lab:labId,slide:idx,returnTo:route.params.returnTo||''})}
function labCoreIndexes(labId){return LABS[labId].slides.map((x,i)=>x.level==='inti'?i:-1).filter(i=>i>=0)}
function labDeepIndexes(labId){return LABS[labId].slides.map((x,i)=>x.level==='pendalaman'?i:-1).filter(i=>i>=0)}
function labLastCoreIndex(labId){const a=labCoreIndexes(labId);return a[a.length-1]??0}
function labRenderHtml(slide){return String(slide.html||'').replaceAll('{{GLUCOSE_THRESHOLD}}',String(SIM_CONST.glucoseThreshold))}
function labStep(group,delta=0){const root=document.querySelector(`[data-lab-step="${group}"]`);if(!root)return;const items=[...root.querySelectorAll('.lab-step-item')];let cur=Number(root.dataset.current||1);cur=Math.max(1,Math.min(items.length,cur+Number(delta||0)));root.dataset.current=cur;items.forEach((el,i)=>el.classList.toggle('shown',i<cur));}
function labHabitToggle(key,checked){const allowed=['aktif','minum','manis','rokok','sumber'];if(!allowed.includes(key))return;state.health=state.health||{habits:[]};const set=new Set(state.health.habits||[]);checked?set.add(key):set.delete(key);state.health.habits=[...set];saveState(false);toast('Rencana kebiasaan tersimpan.');}
function labSyncHabits(){const set=new Set(state.health?.habits||[]);document.querySelectorAll('[data-health-habit]').forEach(el=>el.checked=set.has(el.dataset.healthHabit));}
function labTrySim(preset='normal',follow=''){const map={normal:[65,65,70,90],exercise:[28,66,72,92],drink:[96,68,72,88],lowbp:[62,38,42,90],highglucose:[65,65,70,300]},v=map[preset]||map.normal;state.simulation.hydration=v[0];state.simulation.filtrationPressure=v[1];state.simulation.bloodFlow=v[2];state.simulation.glucoseBlood=v[3];state.simulation.running=false;state.simulation.completed=false;state.simulation.stage=0;state.simulation.prediction={volume:'',concentration:''};if(follow){state.simulation.mode='follow';state.simulation.followSubstance=follow}labNavRuntime.returnToLab={labId:route.params.lab||'lab3',slideId:LABS[route.params.lab||'lab3']?.slides[route.params.slide||0]?.id||''};saveState(false);navigate('simulation')}
function labBackFromSimulation(){const r=labNavRuntime.returnToLab;if(r&&r.slideId){const t=r;labNavRuntime.returnToLab=null;labGo(t.labId,t.slideId,'')}else navigate('materialHub')}
function getAssetSrc(key){if(!key||key==='samples')return null;const parts=String(key).split(':'),kind=parts[0],name=parts.slice(1).join(':');if(name&&ASSETS[kind]&&ASSETS[kind][name])return ASSETS[kind][name];for(const group of Object.values(ASSETS)){if(group&&typeof group==='object'&&group[key])return group[key]}return null}
function labUiMeta(labId){return ({lab1:{n:1,icon:'🧭',focus:'Kenali letak ginjal, jalur urin, dan bagian utama nefron.',cls:'s1'},lab2:{n:2,icon:'🔬',focus:'Temukan bagaimana glomerulus menyaring darah menjadi filtrat.',cls:'s2'},lab3:{n:3,icon:'💧',focus:'Ikuti reabsorpsi, sekresi, dan perjalanan filtrat menjadi urin.',cls:'s3'},lab4:{n:4,icon:'🛡️',focus:'Hubungkan konsep ginjal dengan kebiasaan sehat dan literasi kesehatan.',cls:'s4'}})[labId]||{n:'•',icon:'📘',focus:'Pelajari konsep utama pada stasiun ini.',cls:'s1'}}
function labCoreProgress(labId){labEnsureProgress(labId);const core=LABS[labId].slides.filter(x=>x.level==='inti'),seen=new Set(state.labs[labId].visitedSlideIds||[]),done=core.filter(x=>seen.has(x.id)).length;return {done,total:core.length,pct:core.length?Math.round(done/core.length*100):0}}
function labResumeIndex(labId){labEnsureProgress(labId);const lab=LABS[labId],seen=new Set(state.labs[labId].visitedSlideIds||[]),core=lab.slides.map((x,i)=>x.level==='inti'?i:-1).filter(i=>i>=0),first=core.find(i=>!seen.has(lab.slides[i].id));return first==null?(core[0]||0):first}
function renderMaterialHub(){Object.keys(LABS).forEach(labEnsureProgress);const visited=Object.values(state.labs).filter(x=>x.visited).length,passed=Object.values(state.labs).filter(x=>x.checkpoint.status==='benar').length;setApp(`<section class="material-hub-screen"><div class="material-hero"><div><div class="eyebrow">Materi Pembelajaran · 4 Stasiun</div><h1>Pilih misi belajarmu</h1><p>Mulai dari stasiun mana pun. Selesaikan layar <strong>INTI</strong> untuk Cek Pemahaman; <strong>Pendalaman</strong> tetap opsional. Nefi akan memberi petunjuk di setiap stasiun.</p><div class="material-mode-row"><span class="badge cyan">📘 INTI = jalur utama</span><span class="badge warn">✦ Pendalaman = opsional</span><span class="badge good">✓ Checkpoint lulus ${passed}/4</span></div></div><img class="mascot-img" src="${MASCOT_ASSETS.teaching}" alt="Nefi menunjukkan pilihan stasiun belajar"></div><div class="lab-station-grid">${Object.entries(LABS).map(([id,lab])=>{const st=labStatus(state.labs[id]),core=lab.slides.filter(x=>x.level==='inti').length,deep=lab.slides.length-core,pg=labCoreProgress(id),meta=labUiMeta(id),resume=labResumeIndex(id),started=pg.done>0||state.labs[id].visited,label=state.labs[id].checkpoint.status==='benar'?'Baca lagi':started?'Lanjutkan':'Mulai Stasiun';return `<article class="lab-station-card ${meta.cls}"><div class="lab-station-index" aria-hidden="true">${meta.icon}</div><div class="lab-station-body"><div class="lab-station-kicker">STASIUN ${meta.n}</div><h2>${lab.title.replace(/^Lab \d+ — /,'')}</h2><p>${lab.subtitle}</p><div class="lab-station-focus"><strong>Misi:</strong> ${meta.focus}</div><div class="lab-station-meta"><span class="badge ${st[1]}">${st[0]}</span><span class="badge">${core} INTI</span>${deep?`<span class="badge warn">${deep} Pendalaman</span>`:''}</div><div class="lab-station-progress"><div class="lab-station-progress-head"><span>Progres materi INTI</span><strong>${pg.done}/${pg.total}</strong></div><div class="lab-station-progress-track" role="progressbar" aria-label="Progres materi inti ${lab.title}" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${pg.pct}"><span style="width:${pg.pct}%"></span></div><div class="lab-station-action"><span class="lab-station-status">Checkpoint: ${state.labs[id].checkpoint.status.replaceAll('_',' ')}</span><button class="btn primary" onclick="labNav('${id}',${resume})" aria-label="${label} ${lab.title}">${label} →</button></div></div></div></article>`}).join('')}</div><div class="actions split"><button class="btn" onclick="home()">← Menu Utama</button><span class="statusline">Stasiun dikunjungi <strong>${visited}/4</strong> · Kamu bebas memilih urutan.</span></div></section>`)}
function visitSlide(labId,idx){const l=state.labs[labId],slide=LABS[labId]?.slides[idx];labEnsureProgress(labId);if(!l||!slide)return;l.visited=true;if(!l.visitedSlides.includes(idx))l.visitedSlides.push(idx);if(!l.visitedSlideIds.includes(slide.id))l.visitedSlideIds.push(slide.id);if(l.status==='belum_dipelajari')l.status='sedang_dipelajari';if(l.checkpoint.retryLocked){l.checkpoint.retryLocked=false;l.checkpoint.status='siap_coba_lagi'}saveState(false)}
function renderLab(labId,idx){const lab=LABS[labId];if(!lab){navigate('materialHub');return}idx=Math.max(0,Math.min(Number(idx)||0,lab.slides.length-1));labEnsureProgress(labId);visitSlide(labId,idx);const slide=lab.slides[idx],meta=labUiMeta(labId);let visual='';if(slide.asset==='samples'){visual=`<div class="model-samples"><article class="model-sample"><div class="droplet small"></div><h3>Kehilangan air lebih tinggi</h3><p class="muted">Lebih banyak air dipertahankan melalui reabsorpsi → urin relatif lebih sedikit/pekat.</p></article><article class="model-sample"><div class="droplet light"></div><h3>Cairan tubuh cukup</h3><p class="muted">Retensi air tidak sebesar kondisi dehidrasi → urin relatif lebih banyak/encer.</p></article></div>`}else if(slide.asset){const src=getAssetSrc(slide.asset);if(src)visual=imgFigure(src,slide.alt||'',slide.caption||'','science-figure')}if(!visual&&labId==='lab4'&&slide.id==='l4-sehat'){visual=imgFigure(ASSETS.external.v5_panduan_kesehatan_ginjal,'Infografik berbahasa Indonesia tentang langkah menjaga kesehatan ginjal','Panduan visual untuk kebiasaan menjaga kesehatan ginjal.','science-figure')}
 const dots=lab.slides.map((sl,i)=>`<button class="dot ${sl.level==='pendalaman'?'deep':''} ${i===idx?'active':''} ${state.labs[labId].visitedSlideIds.includes(sl.id)?'visited':''}" aria-label="${sl.level==='pendalaman'?'Pendalaman':'Inti'} ${i+1}: ${esc(sl.title)}" title="${esc(sl.title)}" onclick="labNav('${labId}',${i})">${i+1}</button>`).join(''),c=state.labs[labId].checkpoint,simBtn=['lab2','lab3'].includes(labId)?`<button class="btn good" onclick="labTrySim('normal')">${ICONS.sim} Coba di Simulasi</button>`:'',core=labCoreIndexes(labId),deep=labDeepIndexes(labId),levelBadge=slide.level==='pendalaman'?`<span class="badge lab-level-badge deep">✦ Pendalaman · opsional</span>`:`<span class="badge cyan lab-level-badge">📘 INTI</span>`;let nextControls='';if(slide.level==='inti'){const pos=core.indexOf(idx);if(pos<core.length-1)nextControls=`<button class="btn primary" onclick="labNav('${labId}',${core[pos+1]})">Lanjut Materi →</button>`;else nextControls=`<button class="btn primary" onclick="navigate('checkpoint',{lab:'${labId}'})">Cek Pemahaman →</button>${deep.length?`<button class="btn warn" onclick="labNav('${labId}',${deep[0]})">Buka Pendalaman ✦</button>`:''}`}else{const pos=deep.indexOf(idx);nextControls=pos<deep.length-1?`<button class="btn primary" onclick="labNav('${labId}',${deep[pos+1]})">Pendalaman berikutnya →</button>`:`<button class="btn primary" onclick="navigate('checkpoint',{lab:'${labId}'})">Cek Pemahaman →</button>`}
 const prev=idx>0?idx-1:-1,backOrigin=route.params.returnTo==='simulation'?`<button class="btn good" onclick="navigate('simulation')">← Kembali ke Simulasi</button>`:'',levelIndexes=slide.level==='inti'?core:deep,levelPos=Math.max(0,levelIndexes.indexOf(idx)),levelTotal=Math.max(1,levelIndexes.length),levelPct=Math.round((levelPos+1)/levelTotal*100),readPct=Math.round((idx+1)/lab.slides.length*100),fallback=`<article class="lab-reader-empty"><div class="mascot-inline-note"><img class="mascot-img" src="${MASCOT_ASSETS.thinking}" alt="Nefi memberi tips belajar"><div><h2>Fokus pada ide utama</h2><p>Baca panel materi sambil mencari hubungan <strong>struktur → proses → hasil</strong>. Gunakan bagian “Intinya” sebagai ringkasan.</p></div></div></article>`;setApp(`<section class="lab-reader-screen"><div class="lab-reader-top"><div><div class="lab-breadcrumb"><button class="btn ghost" onclick="navigate('materialHub')">← 4 Stasiun</button><span class="badge">${meta.icon} Stasiun ${meta.n}</span>${levelBadge}${backOrigin}</div><h1>${slide.title}</h1><p>${lab.subtitle}</p><div class="lab-progress-box"><div class="lab-progress-head"><span>${slide.level==='inti'?'Jalur INTI':'Pendalaman'} · ${levelPos+1}/${levelTotal}</span><strong>${levelPct}%</strong></div><div class="lab-progress-rail" role="progressbar" aria-label="Progres bagian ${slide.level}" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${levelPct}"><span style="width:${levelPct}%"></span></div></div></div><img class="mascot-img" src="${slide.level==='pendalaman'?MASCOT_ASSETS.thinking:MASCOT_ASSETS.teaching}" alt="${slide.level==='pendalaman'?'Nefi mengajak berpikir lebih dalam':'Nefi membantu menjelaskan materi'}"></div><div class="lab-reader-grid"><article class="panel content-text lab-reader-content">${labRenderHtml(slide)}${simBtn?`<div class="actions">${simBtn}</div>`:''}<div class="lab-tipline"><span aria-hidden="true">💡</span><div><strong>Tips Nefi:</strong> Setelah membaca, coba ceritakan kembali satu ide dengan bahasamu sendiri sebelum menekan Lanjut.</div></div></article><aside class="lab-reader-visual">${visual||fallback}<p class="compact-note lab-reading-count">Layar ${idx+1} dari ${lab.slides.length} · progres keseluruhan ${readPct}%</p></aside></div><div class="panel lab-map-panel"><div class="lab-map-head"><h3>Peta belajar stasiun</h3><span>Kotak putus-putus = Pendalaman opsional</span></div><div class="lab-slide-scroll"><div class="slide-dots">${dots}</div></div><div class="lab-reader-nav"><button class="btn" onclick="navigate('materialHub')">← Hub Materi</button><div class="actions"><button class="btn" ${prev<0?'disabled':''} onclick="labNav('${labId}',${Math.max(prev,0)})">← Sebelumnya</button>${nextControls}</div></div>${c.status==='siap_coba_lagi'?`<div class="callout warn"><strong>Siap mencoba ulang.</strong> Kamu sudah membuka materi kembali. <button class="btn warn" onclick="navigate('checkpoint',{lab:'${labId}'})">Coba Lagi</button></div>`:''}</div></section>`);labStep('adh',0);labSyncHabits()}
function renderQuestion(q,prefix,answer){const name=`${prefix}_${q.id}`;if(['PG','SJT','Benar Salah'].includes(q.type)){return `<div class="choice-list">${q.options.map(o=>`<label class="choice"><input type="radio" name="${name}" value="${esc(o)}" ${answer===o?'checked':''}><span>${o}</span></label>`).join('')}</div>`}if(q.type==='PG Kompleks'){const arr=Array.isArray(answer)?answer:[];return `<div class="choice-list">${q.options.map(o=>`<label class="choice"><input type="checkbox" name="${name}" value="${esc(o)}" ${arr.includes(o)?'checked':''}><span>${o}</span></label>`).join('')}</div>`}if(q.type==='Menjodohkan'){const obj=answer&&typeof answer==='object'&&!Array.isArray(answer)?answer:{};return `<div class="matching-grid">${q.left.map(l=>`<strong>${l}</strong><select data-match-left="${esc(l)}"><option value="">— pilih pasangan —</option>${q.right.map(r=>`<option value="${esc(r)}" ${obj[l]===r?'selected':''}>${r}</option>`).join('')}</select>`).join('')}</div>`}if(q.type==='Mengurutkan'){const order=Array.isArray(answer)&&answer.length?answer:q.options.slice();return `<ol class="order-list" data-order-list>${order.map((o,i)=>`<li class="order-item" data-value="${esc(o)}"><span>${o}</span><span class="order-controls"><button type="button" aria-label="Naik" onclick="moveOrder(this,-1)">↑</button><button type="button" aria-label="Turun" onclick="moveOrder(this,1)">↓</button></span></li>`).join('')}</ol>`}return ''}
function moveOrder(btn,dir){const li=btn.closest('li'),list=li.parentElement,items=[...list.children],idx=items.indexOf(li),target=idx+dir;if(target<0||target>=items.length)return;if(dir<0)list.insertBefore(li,items[target]);else list.insertBefore(items[target],li)}
function collectAnswer(q,root){if(['PG','SJT','Benar Salah'].includes(q.type)){const el=root.querySelector(`input[name$="_${q.id}"]:checked`);return el?el.value:null}if(q.type==='PG Kompleks')return [...root.querySelectorAll(`input[name$="_${q.id}"]:checked`)].map(x=>x.value);if(q.type==='Menjodohkan'){const obj={};root.querySelectorAll('[data-match-left]').forEach(s=>obj[s.dataset.matchLeft]=s.value);return obj}if(q.type==='Mengurutkan')return [...root.querySelectorAll('[data-order-list] [data-value]')].map(x=>x.dataset.value);return null}
function scoreAnswer(q,a){if(a==null)return 0;if(['PG','SJT','Benar Salah'].includes(q.type))return a===q.correct?1:0;if(q.type==='PG Kompleks'){const c=q.correct,sel=Array.isArray(a)?a:[];const good=sel.filter(x=>c.includes(x)).length,bad=sel.filter(x=>!c.includes(x)).length;return Math.max(0,Math.min(1,(good-bad)/c.length))}if(q.type==='Menjodohkan'){const keys=Object.keys(q.correct);return keys.filter(k=>a[k]===q.correct[k]).length/keys.length}if(q.type==='Mengurutkan'){return q.correct.filter((x,i)=>a[i]===x).length/q.correct.length}return 0}
function answerComplete(q,a){if(a==null)return false;if(['PG','SJT','Benar Salah'].includes(q.type))return !!a;if(q.type==='PG Kompleks')return a.length>0;if(q.type==='Menjodohkan')return q.left.every(k=>a[k]);if(q.type==='Mengurutkan')return a.length===q.correct.length;return false}
function correctText(q){if(Array.isArray(q.correct))return q.correct.join(' · ');if(q.correct&&typeof q.correct==='object')return Object.entries(q.correct).map(([a,b])=>`${a} → ${b}`).join(' | ');return String(q.correct)}
function renderCheckpoint(labId){const cp=state.labs[labId].checkpoint,qs=CHECKPOINTS[labId];if(cp.retryLocked){setApp(`<section class="panel center" style="max-width:850px;margin:6vh auto"><img class="mascot-img" src="${MASCOT_ASSETS.thinking}" alt="Nefi mengajak berpikir lagi" style="width:130px;margin:0 auto 8px"><div class="eyebrow">Cek Pemahaman</div><h1>Perlu membaca ulang</h1><p class="lead" style="margin:auto">Jawaban sebelumnya belum seluruhnya tepat. Buka kembali materi ${LABS[labId].title}, lalu tombol retry akan aktif. Ini tidak mengunci menu lain karena mode akses adalah Bebas.</p><div class="actions" style="justify-content:center"><button class="btn primary" onclick="navigate('lab',{lab:'${labId}',slide:0})">Buka Ulang Materi</button><button class="btn" onclick="home()">⌂ Menu Utama</button></div></section>`);return}
setApp(`<section><div class="pagehead"><div><div class="eyebrow">Cek Pemahaman Formatif</div><h1>${LABS[labId].title}</h1><p>Tiga pertanyaan singkat. Hasil checkpoint <strong>tidak masuk Nilai Evaluasi Akhir</strong>.</p></div><div class="mascot-question"><img class="mascot-img" src="${MASCOT_ASSETS.thinking}" alt="Nefi mengajak memikirkan jawaban"><span class="badge cyan">Percobaan ${cp.attempts+1}</span></div></div><div id="cpRoot">${qs.map((q,i)=>`<article class="qbox"><div class="eval-meta"><span class="badge">${q.id}</span><span class="badge cyan">${q.type}</span></div><h3>${i+1}. ${q.prompt}</h3>${renderQuestion(q,'cp',null)}</article>`).join('')}</div><div class="actions split"><button class="btn" onclick="navigate('lab',{lab:'${labId}',slide:${labLastCoreIndex(labId)}})">← Kembali ke Materi</button><button class="btn primary" onclick="submitCheckpoint('${labId}')">Periksa Jawaban</button></div></section>`)}
function submitCheckpoint(labId){const root=document.getElementById('cpRoot'),qs=CHECKPOINTS[labId],cp=state.labs[labId].checkpoint;const answers=qs.map(q=>collectAnswer(q,root));if(answers.some((a,i)=>!answerComplete(qs[i],a))){toast('Lengkapi semua jawaban terlebih dahulu.');return}cp.attempts++;const scores=qs.map((q,i)=>scoreAnswer(q,answers[i]));const failed=qs.filter((q,i)=>scores[i]<.999);if(!failed.length){cp.status='benar';cp.retryLocked=false;cp.lastFailedIds=[];state.labs[labId].status='selesai';saveState(false);showModal('✓ Checkpoint berhasil',`<div class="mascot-feedback"><img class="mascot-img" src="${MASCOT_ASSETS.thumbs}" alt="Nefi memberi jempol"><div><p>Semua jawaban tepat. ${LABS[labId].title} berstatus <strong>Selesai</strong>.</p><p>Checkpoint ini tidak memengaruhi Nilai Evaluasi Akhir.</p></div></div>`,[{label:'Kembali ke Hub',action:`navigate('materialHub')`,primary:true},{label:'Menu Utama',action:'home()'}])}else{cp.status='salah_perlu_baca_ulang';cp.retryLocked=true;cp.lastFailedIds=failed.map(x=>x.id);state.labs[labId].status='perlu_ulang';saveState(false);const hints=failed.map(q=>`<li><strong>${q.id}:</strong> ${q.hint}</li>`).join('');showModal('↻ Belum seluruhnya tepat',`<div class="mascot-feedback"><img class="mascot-img" src="${MASCOT_ASSETS.thinking}" alt="Nefi mengajak meninjau materi"><div><p>Gunakan petunjuk berikut tanpa membocorkan jawaban lengkap:</p><ul>${hints}</ul><p>Buka kembali materi Lab ini. Setelah salah satu layar materi dibuka, retry akan aktif.</p></div></div>`,[{label:'Baca Ulang Materi',action:`navigate('lab',{lab:'${labId}',slide:0})`,primary:true},{label:'Menu Utama',action:'home()'}])}}
function showModal(title,body,buttons=[{label:'Tutup',action:'closeModal()'}]){document.getElementById('modalRoot').innerHTML=`<div class="modal-back" role="dialog" aria-modal="true"><div class="modal"><h2>${title}</h2>${body}<div class="actions right">${buttons.map(b=>`<button class="btn ${b.primary?'primary':''}" onclick="closeModal();${b.action}">${b.label}</button>`).join('')}</div></div></div>`}
function closeModal(){document.getElementById('modalRoot').innerHTML=''}
function simClamp(n,min,max){return Math.max(min,Math.min(max,n))}
/*
 Model fisiologi ilustratif SMP (bukan alat diagnosis).
 - GFRrel dinormalisasi: tekanan 65 + aliran 70 = 100%; slider menggambarkan perubahan relatif,
   sedangkan ginjal sehat nyata memiliki autoregulasi yang menahan perubahan GFR.
 - Satuan volume = L/hari; osmolalitas = mOsm/kg (diasumsikan ~mOsm/L untuk model sederhana).
 - Beban osmole dasar dibuat 540 mOsm/hari agar rentang volume 0,45 L tetap berada di sekitar
   batas pemekatan ilustratif 1200 mOsm/kg. Glukosa urin menambah osmole dan air osmotik.
 - Air ditelusuri per 1.000 unit air simbolis dari ±180 L filtrat/hari.
*/
const SIM_CONST=Object.freeze({glucoseThreshold:180});
function simCalc(overrides=null){
 const base=state.simulation||{},s=overrides?Object.assign({},base,overrides):base;
 const h=Number(s.hydration??65),p=Number(s.filtrationPressure??65),b=Number(s.bloodFlow??70),g=Number(s.glucoseBlood??90);
 const rawFlow=.58*p+.42*b,normalRaw=.58*65+.42*70;
 const gfrRel=Math.round(simClamp(100+(rawFlow-normalRaw)*1.4,35,130)*10)/10;
 const baseUrineLiters=simClamp(1.35+(h-65)*.025+(gfrRel-100)*.005,.45,2.55);
 const glucoseFiltered=g*gfrRel/100;
 const glucoseReabsorbed=Math.min(glucoseFiltered,SIM_CONST.glucoseThreshold);
 const glucoseUrine=Math.max(0,glucoseFiltered-glucoseReabsorbed);
 const glucoseUrineFraction=glucoseFiltered>0?glucoseUrine/glucoseFiltered:0;
 const glucoseInUrine=glucoseUrine>1e-6;
 const effectiveGlucoseThreshold=SIM_CONST.glucoseThreshold*100/gfrRel;
 const glucoseOsmoles=glucoseUrine*2.5; // indeks beban glukosa -> ekuivalen mOsm/hari untuk visualisasi
 const osmoticVolume=glucoseInUrine?glucoseOsmoles/300:0; // air mengikuti osmole menuju ~300 mOsm/L
 const urineLiters=simClamp(baseUrineLiters+osmoticVolume,.45,glucoseInUrine?5:2.55);
 const baseSolute=540,totalSolute=baseSolute+glucoseOsmoles;
 const osmolality=Math.round((totalSolute/urineLiters)*10)/10;
 const concentration=Math.round(simClamp((osmolality-50)/(1200-50)*100,0,100));
 const urineVol=Math.round(simClamp(urineLiters/5*100,8,100));
 const pigmentIndex=Math.round(simClamp(50+(1.35/urineLiters-1)*30,12,96));
 const waterUrinePer1000=Math.round((urineLiters/180*1000)*10)/10;
 const waterCollecting=Math.round((150-waterUrinePer1000)*10)/10;
 const waterSegments={proximal:650,henle:150,distal:50,collecting:waterCollecting,urine:waterUrinePer1000};
 const waterReabs=Math.round((100-waterUrinePer1000/10)*10)/10;
 const waterUrinePer100=waterUrinePer1000/10; // kompatibilitas data lama
 const glucoseWaterPer1000=Math.round((osmoticVolume/180*1000)*10)/10;
 const flowNorm=simClamp((urineLiters-.45)/(2.55-.45),0,1);
 const ureaExcretionFraction=Math.round((.40+.20*flowNorm)*1000)/1000;
 return {
  filtration:Math.round(gfrRel),gfrRel,baseUrineLiters,urineLiters,urineVol,osmolality,concentration,
  baseSolute,totalSolute,pigmentIndex,waterReabs,waterUrinePer100,waterUrinePer1000,waterSegments,
  glucoseFiltered,glucoseReabsorbed,glucoseUrine,glucoseUrineFraction,glucoseInUrine,effectiveGlucoseThreshold,
  glucoseOsmoles,osmoticVolume,glucoseWaterPer1000,ureaExcretionFraction,ionUrineFraction:.01
 };
}
