function simMissionEligible(key,c){if(key==='concentrated')return c.osmolality>=900;if(key==='dilute')return c.osmolality<=300;if(key==='glucose')return c.glucoseUrine>0&&simGlucoseParticleCount(c,16)>0;if(key==='osmotic')return c.glucoseUrine>0&&c.osmoticVolume>=.8;return false}
