function simStage(i){const n=Math.max(0,Math.min(4,Number(i)));state.simulation.stage=n;state.simulation.running=false;simStopLoop(false);simRuntime.progress=simClamp(n/5+.055,0,.96);state.simulation.completed=false;simRuntime.completed=false;simQueueSave();simUpdateUI(false)}
function simSet(key,val){const s=state.simulation;if(['hydration','filtrationPressure','bloodFlow','glucoseBlood','speed'].includes(key))s[key]=Number(val);else s[key]=val;if(key==='mode'){s.running=false;simStopLoop(false);if(val==='step')simRuntime.progress=simClamp(s.stage/5+.055,0,.96)}if(key==='followSubstance')simParticleInfo(val,false);if(['hydration','filtrationPressure','bloodFlow','glucoseBlood'].includes(key)){s.completed=false;simRuntime.completed=false}s.lastRun=s.lastRun||null;simQueueSave();simUpdateUI(false);if(s.running)simStartLoop()}
function simPreset(name){const map={normal:[65,65,70,90],exercise:[28,66,72,92],drink:[96,68,72,88],lowbp:[62,38,42,90],highglucose:[65,65,70,300]},v=map[name]||map.normal;state.simulation.hydration=v[0];state.simulation.filtrationPressure=v[1];state.simulation.bloodFlow=v[2];state.simulation.glucoseBlood=v[3];state.simulation.prediction={volume:'',concentration:''};state.simulation.completed=false;state.simulation.running=false;simRuntime.completed=false;simStopLoop(false);simQueueSave();simUpdateUI(false);toast('Kondisi diubah. Buat prediksi, lalu jalankan simulasi.')}
function simPredict(kind,val){if(!state.simulation.prediction)state.simulation.prediction={volume:'',concentration:''};state.simulation.prediction[kind]=val;simQueueSave();simUpdateUI(false)}
function simStartLoop(){if(simRuntime.raf||!state.simulation.running||route.name!=='simulation'||document.hidden)return;if(window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches){state.simulation.running=false;simUpdateUI(false);return}simRuntime.raf=requestAnimationFrame(simLoop)}
