function runSimulation(){const s=state.simulation;if(s.running){s.running=false;simStopLoop(false);simQueueSave();simUpdateUI(false);return}if(!s.prediction?.volume||!s.prediction?.concentration){toast('Pilih prediksi volume dan kepekatan terlebih dahulu.');document.querySelector('.sim-prediction')?.scrollIntoView({behavior:'smooth',block:'center'});return}if(s.completed||simRuntime.progress>=.995){s.completed=false;simRuntime.completed=false;s.stage=0;simRuntime.progress=.02}s.running=true;s.lastRun=new Date().toISOString();simQueueSave();simUpdateUI(false);simStartLoop()}
