 {id:'express',name:'Nefron Express',tag:'02 · Antarkan zat',desc:'Pilih segmen nefron sesuai zat, proses, dan arah perjalanannya.',time:'8 misi · tanpa timer',lab:'lab3',slide:'l3-reabsorpsi',asset:'game_glukosa.webp'},
 {id:'water',name:'1000 Tetes Air',tag:'03 · Atur keseimbangan',desc:'Kembalikan air ke darah sesuai kebutuhan tubuh.',time:'3 tahap · 3 kondisi',lab:'lab3',slide:'l3-cairan',asset:'game_air.webp'},
 {id:'boss',name:'Urine Factory',tag:'04 · Tantangan akhir',desc:'Kelola filtrasi, reabsorpsi, sekresi, hingga urin akhir.',time:'4 fase · rangkuman',lab:'lab3',slide:'l3-proses',asset:'game_urea.webp'}
