const v8Eval=renderEvaluation;renderEvaluation=function(){v8Eval();document.querySelector('.pagehead p')?.remove();document.querySelector('.mascot-question img')?.remove();const side=document.querySelector('.eval-side');if(side){side.querySelector('p')?.remove();if(innerWidth<800){const d=document.createElement('details');d.className='v8-eval-nav';d.innerHTML='<summary>Navigasi 15 soal</summary>';side.before(d);d.append(side)}}};

/* v9: centered workspaces, restored nephron reference, explicit session exit */
const V9={view:'process',picture:'full',mobilePanel:'process'};
const V9_PROFILES_KEY=APP_KEY+':student-profiles';
function v9ProfileKey(name,cls){return JSON.stringify([name.trim().toLocaleLowerCase('id'),cls.trim().toLocaleLowerCase('id')])}
function v9ReadProfiles(){try{const v=JSON.parse(localStorage.getItem(V9_PROFILES_KEY)||'{}');return v&&typeof v==='object'&&!Array.isArray(v)?v:{}}catch(e){return {}}}
function exitApplication(){
 let archived=true;simStopLoop();arcadeStop();state.simulation.running=false;const session=arcadeSession();if(session)session.paused=true;
 if(state.student.name&&state.student.className){const profiles=v9ReadProfiles();profiles[v9ProfileKey(state.student.name,state.student.className)]=deepClone(state);try{localStorage.setItem(V9_PROFILES_KEY,JSON.stringify(profiles))}catch(e){archived=false}}
 try{localStorage.removeItem(APP_KEY)}catch(e){}state=defaultState();state.ui.signedOut=true;saveState(false);document.getElementById('modalRoot').innerHTML='';route={name:'opening',params:{}};render();window.scrollTo(0,0);toast(archived?'Sudah keluar. Isi nama dan kelas untuk masuk kembali.':'Sudah keluar. Identitas direset, tetapi arsip progres sesi ini gagal disimpan.');
}
submitIdentity=function(){const name=document.getElementById('name').value.trim(),cls=document.getElementById('className').value.trim();if(!name||!cls){toast('Nama dan kelas perlu diisi terlebih dahulu.');return}const saved=v9ReadProfiles()[v9ProfileKey(name,cls)];state=saved?mergeDeep(defaultState(),saved):defaultState();state.student={name,className:cls};state.ui.signedOut=false;state.simulation.running=false;if(state.arcade?.session)state.arcade.session.paused=true;saveState(false);navigate(state.onboarding.completed?'dashboard':'guide',{onboarding:!state.onboarding.completed})};
const v9Navigate=navigate;
navigate=function(name,params={}){if((!state.student.name||!state.student.className)&&!['opening','identity'].includes(name)){name='identity';params={}}v9Navigate(name,params)};
const v9Header=header;
header=function(){const h=v9Header();if(!h)return state.student.name&&state.student.className?`<header class="topbar"><div class="brand"><div><strong>Nefi’s Kidney Lab</strong><span>${esc(state.student.name)} · ${esc(state.student.className)}</span></div></div><button class="btn v9-exit" onclick="exitApplication()">⏻ Keluar</button></header>`:'';return h.replace('</header>','<button class="btn v9-exit" onclick="exitApplication()" title="Keluar dan masukkan ulang identitas saat kembali" aria-label="Keluar aplikasi">⏻ <span>Keluar</span></button></header>')};
const v9Identity=renderIdentity;
renderIdentity=function(){v9Identity();const panel=document.querySelector('main>section');if(panel){panel.classList.add('v9-identity');panel.style.margin='0 auto';panel.style.maxWidth='720px'}document.getElementById('name').setAttribute('autocomplete','off');document.getElementById('className').setAttribute('autocomplete','off')};
// Restore the stable original tab behavior. The whole arena stays visible on desktop.
