function v9SimView(view){if(!['process','pictures','health','results'].includes(view))return;V9.view=view;document.querySelectorAll('[data-v9-view]').forEach(e=>{const on=e.dataset.v9View===view;e.setAttribute('aria-selected',String(on));e.tabIndex=on?0:-1});for(const [id,k] of [['v9Process','process'],['v9Pictures','pictures'],['v9Health','health'],['v9Results','results']]){const p=document.getElementById(id);if(p)p.hidden=k!==view}if(view==='pictures')v9SyncPicture();if(view==='process'){simUiApplyResponsiveSvg();simPositionParticles(simRuntime.progress)}}
function v9ViewKey(e){const tabs=[...document.querySelectorAll('[data-v9-view]')],i=tabs.indexOf(e.target);if(i<0)return;let n;if(e.key==='ArrowRight')n=(i+1)%tabs.length;else if(e.key==='ArrowLeft')n=(i+tabs.length-1)%tabs.length;else if(e.key==='Home')n=0;else if(e.key==='End')n=tabs.length-1;else return;e.preventDefault();v9SimView(tabs[n].dataset.v9View);tabs[n].focus()}
function v9Picture(id){if(!['full','stage','kidney','corpuscle'].includes(id))return;V9.picture=id;v9SyncPicture()}
function v9SyncPicture(){const img=document.getElementById('v9NephronImage');if(!img)return;const choices={full:[ASSETS.generated['sim_nephron_full.webp'],'Nefron utuh: glomerulus, tubulus, lengkung Henle, dan duktus kolektivus.'],stage:[simImg(),'Detail semi-realistis tahap '+(state.simulation.stage+1)+': '+SIM_STAGES[state.simulation.stage].title+'.'],kidney:[V7_ASSETS.kidney,'Potongan ginjal: kulit ginjal, medula, pelvis, dan ureter.'],corpuscle:[V7_ASSETS.corpuscle,'Glomerulus di dalam kapsula Bowman: tempat filtrasi plasma.']};const [src,caption]=choices[V9.picture];if(img.getAttribute('src')!==src)img.src=src;img.alt=caption;img.setAttribute('aria-label','Perbesar: '+caption);document.getElementById('v9PictureCaption').textContent=caption+' Ketuk gambar untuk memperbesar.';document.querySelectorAll('[data-v9-picture]').forEach(e=>e.setAttribute('aria-pressed',String(e.dataset.v9Picture===V9.picture)))}
const v9HealthUpdate=simHealthUpdate;const V9_HEALTH_CACHE=new WeakMap();
simHealthUpdate=function(c){const current=document.getElementById('simHealthCard');const assessment=simHealthAssess(c,state);const key=JSON.stringify([assessment.level,assessment.items.map(x=>x.id)]);if(!current||V9_HEALTH_CACHE.get(current)!==key){v9HealthUpdate(c);if(current)V9_HEALTH_CACHE.set(current,key)}const card=document.getElementById('simHealthCard');if(!document.querySelector('.v9-sim')||!card)return;const titles=['Perhatikan','Kebiasaan yang membantu','Kapan meminta bantuan'];card.querySelectorAll('.sim-health-item>b').forEach((e,i)=>e.textContent=titles[i]);card.querySelector('.sim-health-title>span:last-child').textContent='Sesuai kondisi simulasi';};
const v9App=setApp;
setApp=function(html){v9App(html);const main=document.getElementById('mainContent')||document.querySelector('main.shell');if(!main)return;main.classList.add('v9-screen');main.dataset.screen=route.name;};

function v9MobilePanel(p){V9.mobilePanel=p;document.querySelector('.v9-workspace')?.classList.toggle('v9-show-controls',p==='settings');document.querySelectorAll('[data-v9-mobile]').forEach(e=>e.setAttribute('aria-pressed',String(e.dataset.v9Mobile===p)));}
const v9Run=runSimulation;runSimulation=function(){const ready=!!(state.simulation.prediction?.volume&&state.simulation.prediction?.concentration);v9Run();if(document.querySelector('.v9-sim')){if(ready&&!state.simulation.completed)v9SimView('process');if(innerWidth<800)v9MobilePanel(ready?'process':'settings')}};
const v9Reset=resetSimulation;resetSimulation=function(){v9Reset();if(document.querySelector('.v9-sim'))v9SimView('process')};
const v9Repeat=simRepeat;simRepeat=function(){v9Repeat();if(document.querySelector('.v9-sim')){v9SimView('process');simUiTab('conditions');if(innerWidth<800)v9MobilePanel('settings')}};

/* v10: let the diagram own the main panel; move reading material beside it. */
const V10={side:'notes'};
const v10Render=renderSimulation;
renderSimulation=function(){
 v10Render();const root=document.getElementById('simRoot');root.classList.add('v10-sim');
 const process=document.getElementById('v9Process'),side=root.querySelector('.v9-control'),core=side.querySelector('.sim-control-core'),settings=side.querySelector('.sim-control-tabs');
 const notes=document.createElement('section');notes.id='v10ProcessNotes';notes.className='v10-process-notes';notes.setAttribute('aria-label','Keterangan proses simulasi');notes.innerHTML='<h2>Keterangan proses</h2>';
 for(const el of [document.getElementById('v7StageRead'),process.querySelector('.sim-quickstats'),process.querySelector('.sim-legend'),document.getElementById('simNarration'),process.querySelector('.sim-scale-note')])if(el)notes.append(el);
 const mode=core.querySelector('.sim-control-group');if(mode?.querySelector('.sim-modebar'))document.getElementById('simPanelConditions').prepend(mode);
 core.querySelector('h2').textContent='Kontrol simulasi';
 const switches=document.createElement('div');switches.className='v10-side-switch';switches.setAttribute('aria-label','Pilih isi panel samping');switches.innerHTML='<button data-v10-side="notes" aria-pressed="true" aria-controls="v10ProcessNotes" onclick="v10Side(\'notes\')">Keterangan</button><button data-v10-side="settings" aria-pressed="false" aria-controls="v10Settings" onclick="v10Side(\'settings\')">Kondisi & prediksi</button>';settings.id='v10Settings';settings.before(switches);side.append(notes);
 const zoom=document.getElementById('v7Zoom');const tools=document.createElement('div');tools.className='v10-process-tools';tools.innerHTML='<span id="v10FocusLabel">Fokus tahap aktif</span>';if(zoom)tools.append(zoom);process.querySelector('.sim-diagram-wrap').before(tools);
 V7SIM.wide=false;v10Side('notes');simUiApplyResponsiveSvg();simPositionParticles(simRuntime.progress);
};
function v10Side(name){if(!['notes','settings'].includes(name))return;V10.side=name;const notes=document.getElementById('v10ProcessNotes'),settings=document.getElementById('v10Settings');if(notes)notes.hidden=name!=='notes';if(settings)settings.hidden=name!=='settings';document.querySelectorAll('[data-v10-side]').forEach(e=>e.setAttribute('aria-pressed',String(e.dataset.v10Side===name)))}
const v10UiTab=simUiTab;simUiTab=function(name,focus=false,scroll=false){v10UiTab(name,focus,false);if(document.querySelector('.v10-sim'))v10Side('settings')};
const v10MobilePanel=v9MobilePanel;v9MobilePanel=function(name){v10MobilePanel(name);if(name==='settings'&&document.querySelector('.v10-sim'))v10Side('settings')};
const v10Run=runSimulation;runSimulation=function(){const ready=!!(state.simulation.prediction?.volume&&state.simulation.prediction?.concentration);v10Run();if(ready&&!state.simulation.completed&&document.querySelector('.v10-sim'))v10Side('notes')};
// The same focus button now also enlarges the active segment on laptops.
simUiApplyResponsiveSvg=function(){const svg=document.getElementById('simSvg');if(!svg)return;const boxes=['25 65 430 280','230 160 300 240','335 270 250 290','480 230 360 225','720 255 260 435'];const focus=!V7SIM.wide;svg.setAttribute('viewBox',focus?boxes[simClamp(Number(state.simulation.stage)||0,0,4)]:'0 25 980 665');svg.classList.toggle('v7focus',focus);const button=document.getElementById('v7Zoom');if(button){button.textContent=focus?'Lihat seluruh nefron':'Perbesar tahap aktif';button.setAttribute('aria-label',button.textContent)}const label=document.getElementById('v10FocusLabel');if(label)label.textContent=focus?'Fokus tahap '+(state.simulation.stage+1):'Seluruh nefron'};

const V11_ICONS={"home": "assets/images/home.png", "material": "assets/images/material.png", "simulation": "assets/images/simulation.png", "game": "assets/images/game.png", "reflection": "assets/images/reflection.png", "evaluation": "assets/images/evaluation.png", "results": "assets/images/results.png", "objectives": "assets/images/objectives.png", "help": "assets/images/help.png", "anatomy": "assets/images/anatomy.png", "filtration": "assets/images/filtration.png", "transport": "assets/images/transport.png", "health": "assets/images/health.png", "back": "assets/images/back.png", "next": "assets/images/next.png", "zoom": "assets/images/zoom.png", "exit": "assets/images/exit.png", "close": "assets/images/close.png"};
const V11_DEPTH={
'l1-tubuh':['Dua jalur, dua fungsi','Darah membawa zat menuju ginjal dan kembali ke peredaran. Urin mengalir melalui ureter menuju kandung kemih. Ureter bukan pembuluh darah; urin tidak kembali ke jantung lewat ureter.','Saat kandung kemih terisi, ginjal tetap membentuk urin. Penyimpanan dan pembentukan dilakukan oleh organ berbeda.','Mengapa sumbatan ureter dapat mengganggu ginjal meski kandung kemih belum penuh?','Aliran dari ginjal terhambat sebelum mencapai kandung kemih. Gangguan aliran di satu bagian dapat memengaruhi bagian di hulunya.','Ginjal membentuk urin','Ureter mengalirkan urin','Kandung kemih menyimpan'],
'l1-penting':['Menjaga kondisi internal','Sel membutuhkan lingkungan cairan yang relatif stabil. Ginjal mengatur pengeluaran air, elektrolit, dan sisa metabolisme. Hasil penyaringan awal masih banyak mengandung zat berguna; tugas tubulus adalah memilih kembali apa yang dipertahankan.','Membuang semua filtrat akan membuat tubuh kehilangan air dan zat berguna. Reabsorpsi sama pentingnya dengan filtrasi.','Mengapa ginjal tidak tepat disebut hanya saringan sampah?','Ginjal juga mempertahankan zat yang dibutuhkan dan menyesuaikan komposisi cairan tubuh.','Cairan darah berubah','Nefron menyesuaikan zat','Keseimbangan tubuh dijaga'],
'l1-penampang':['Hubungkan bagian dengan pekerjaan','Korteks adalah daerah luar ginjal; medula berisi piramida ginjal. Pelvis menampung aliran urin sebelum masuk ureter. Ini adalah pembagian anatomi, sedangkan filtrasi, reabsorpsi, dan sekresi adalah nama proses.','Jangan menukar kata medula dengan kandung kemih: keduanya berada di tempat dan skala yang berbeda.','Apakah pelvis bertugas menyaring sel darah?','Tidak. Filtrasi berlangsung pada korpuskulum ginjal; pelvis terutama mengumpulkan aliran urin.','Korteks: korpuskulum','Medula: lengkung & saluran','Pelvis: aliran ke ureter'],
'l1-nefron':['Organ tersusun atas unit kerja','Satu nefron mencakup korpuskulum ginjal dan tubulus. Glomerulus adalah anyaman kapiler di dalam kapsula Bowman. Duktus kolektivus menerima cairan dari beberapa nefron; diagram sekolah sering menampilkannya sebagai satu rangkaian.','Satu gambar nefron mewakili banyak unit yang bekerja bersamaan, bukan satu-satunya saluran dalam ginjal.','Apa perbedaan glomerulus dan kapsula Bowman?','Glomerulus berisi darah di dalam kapiler; kapsula Bowman menerima filtrat yang keluar melewati penghalang filtrasi.','Ginjal: organ','Nefron: unit kerja','Glomerulus & tubulus'],
'l1-ekskresi':['Ekskresi dan pengeluaran feses','Ekskresi membuang sisa metabolisme. Pengeluaran feses terutama mengeluarkan sisa bahan dalam saluran cerna yang tidak diserap. Paru mengeluarkan karbon dioksida, kulit mengeluarkan keringat, dan ginjal mengatur urin.','Urea terbentuk terutama di hati dari pengolahan nitrogen, lalu dibawa darah ke ginjal untuk dikeluarkan.','Mengapa urea tidak harus dibuat di ginjal agar dapat keluar lewat urin?','Darah mengangkut zat antarkomponen tubuh; organ pembentuk dan organ pengeluar zat dapat berbeda.','Metabolisme menghasilkan sisa','Darah mengangkut sisa','Organ ekskresi mengeluarkan'],
'l1-lokasi':['Baca dua aliran secara terpisah','Ikuti jalur darah dari aferen, glomerulus, eferen, hingga kapiler di sekitar tubulus. Ikuti jalur filtrat mulai dari Bowman sampai kolektivus. Kedua cairan dipisahkan oleh dinding biologis; perpindahan zat terjadi melintasi dinding itu.','Lengkung Henle masuk ke medula. Kapiler di sekitarnya memungkinkan air dan zat yang direabsorpsi kembali ke sirkulasi.','Apakah darah mengalir melalui rongga tubulus pada ginjal normal?','Tidak. Darah berada di pembuluh; filtrat berada di dalam tubulus.','Darah di pembuluh','Zat melintasi dinding','Filtrat di tubulus'],
'l1-fakta':['Memaknai angka, bukan menghafal','Angka filtrasi harian adalah volume kumulatif cairan yang tersaring berkali-kali sepanjang hari. Angka itu bukan jumlah air yang harus diminum, bukan volume darah tubuh, dan bukan volume urin. Nilai orang dewasa tidak langsung diterapkan pada siswa.','Contoh ilustratif: 180 L filtrat dikurangi 178,5 L air yang kembali menghasilkan 1,5 L urin.','Mengapa volume filtrat sehari dapat lebih besar daripada seluruh cairan tubuh?','Cairan beredar dan diproses berulang, sehingga volumenya dijumlahkan sepanjang waktu.','Volume kumulatif per hari','Sebagian besar kembali','Urin hanya sebagian kecil'],
'l1-mengatur':['Fungsi hormonal ginjal','Ginjal ikut mengatur tekanan darah melalui sistem renin, mendukung pembentukan sel darah merah melalui eritropoietin, dan membantu mengaktifkan vitamin D. Fungsi ini berbeda dari kerja pengangkutan zat di tubulus.','Masalah ginjal dapat berkaitan dengan lebih dari perubahan urin karena ginjal terhubung dengan banyak sistem tubuh.','Apakah eritropoietin berarti ginjal membuat seluruh sel darah merah?','Tidak. Hormon tersebut merangsang pembentukan sel darah merah terutama di sumsum tulang.','Ginjal memberi sinyal','Organ lain merespons','Tekanan, darah & mineral'],
'l2-nefron':['Penyaringan diikuti pemrosesan','Filtrasi memindahkan sebagian cairan plasma ke Bowman. Setelah itu, tubulus mengubah komposisinya. Kapiler dan tubulus berdekatan agar perpindahan zat dapat berlangsung; dekat tidak berarti rongganya menyatu.','Glukosa dapat ditemukan dalam filtrat awal walaupun urin akhir normal hampir tidak mengandung glukosa.','Mengapa tidak cukup memeriksa isi filtrat untuk memprediksi urin akhir?','Filtrat masih mengalami reabsorpsi dan sekresi sebelum keluar.','Filtrasi membentuk filtrat','Tubulus mengubah komposisi','Urin akhir terbentuk'],
'l2-disaring':['Ukuran, sifat, dan jumlah','Air serta banyak zat terlarut kecil dapat tersaring. Sel darah dan sebagian besar protein besar dipertahankan. Jumlah zat yang tersaring juga dipengaruhi konsentrasi di plasma dan banyaknya cairan yang difiltrasi.','Dua zat sama-sama kecil belum tentu berakhir dalam jumlah sama di urin: pemrosesan tubulusnya bisa berbeda.','Apakah zat yang lolos berarti pasti tidak dibutuhkan?','Tidak. Glukosa dan banyak ion berguna juga lolos, kemudian diambil kembali sesuai prosesnya.','Plasma membawa berbagai zat','Penghalang memilah','Air & zat kecil masuk filtrat'],
'l2-filtrasi':['Gaya pendorong dan filtrat awal','Tekanan darah dalam kapiler membantu mendorong filtrasi. Tekanan cairan di Bowman dan tarikan osmotik protein plasma menentang perpindahan itu. Filtrasi adalah hasil keseimbangan gaya, bukan lubang saringan pasif tanpa pengaturan.','Jika semua air tersaring langsung dikeluarkan, kehilangan air akan sangat besar. Tubulus mengubah hasil awal tersebut.','Mengapa disebut filtrat awal, bukan langsung urin akhir?','Komposisinya masih berubah melalui reabsorpsi dan sekresi.','Tekanan mendorong filtrasi','Filtrat masuk Bowman','Tubulus memproses ulang'],
'l2-game':['Batas analogi permainan','Pada game, satu sprite mewakili jenis partikel, bukan jumlah molekul nyata. Keran mengajarkan keputusan arah; glomerulus nyata tidak memiliki keran yang diputar tangan. Tanyakan selalu bagian analogi mana yang membantu dan mana yang disederhanakan.','Mengarahkan sel darah ke jalur darah benar untuk penghalang normal. Memasukkan semua zat kecil ke filtrat belum menyelesaikan pembentukan urin.','Sesudah glukosa masuk filtrat pada game, proses apa yang harus terjadi berikutnya?','Reabsorpsi di tubulus proksimal mengembalikan glukosa ke darah dalam keadaan normal.','Sprite = jenis zat','Keran = analogi arah','Ginjal nyata lebih kompleks'],
'l2-penghalang':['Tiga komponen penghalang','Endotel berpori, membran basal, dan celah filtrasi antarpodosit membentuk satu kesatuan. Ukuran dan sifat molekul memengaruhi lintasan. Kerusakan penghalang dapat mengubah selektivitas; pemeriksaan nyata tetap diperlukan untuk menilai penyebabnya.','Saringan dapur hanya membantu membayangkan pemisahan ukuran. Penghalang biologis memiliki sel dan sifat permukaan yang jauh lebih kompleks.','Mengapa protein besar biasanya tertahan walaupun air dapat lewat?','Sifat penghalang membatasi lintasan protein besar sambil memungkinkan air dan banyak zat kecil melewatinya.','Darah dalam kapiler','Tiga lapis penghalang','Filtrat di ruang Bowman'],
'l2-angka':['Pisahkan laju dan volume','Laju filtrasi adalah volume per satuan waktu. Volume harian diperoleh dari laju yang dikumpulkan selama sehari. Angka ilustratif 125 mL/menit setara sekitar 180 L/hari jika diasumsikan tetap selama 24 jam.','125 × 60 × 24 = 180.000 mL = 180 L. Ini filtrat, bukan urin dan bukan kebutuhan minum.','Mengapa hasil perhitungan itu tidak boleh menjadi target minum?','Sebagian besar filtrat direabsorpsi; perhitungan menunjukkan proses internal yang berulang.','125 mL tiap menit (contoh)','Dikalikan 1.440 menit','180 L filtrat, bukan urin'],
'l2-autoregulasi':['Menjaga laju relatif stabil','Ginjal dapat menyesuaikan hambatan pembuluh dan sinyal dari tubulus agar filtrasi tidak mengikuti setiap perubahan kecil tekanan secara langsung. Kemampuan ini memiliki batas. Slider aplikasi menyederhanakan hubungan untuk belajar.','Jika tekanan sistemik naik sedikit, laju filtrasi pada ginjal sehat tidak selalu naik dengan perbandingan yang sama.','Apa yang perlu diingat saat membandingkan slider dan tubuh nyata?','Hubungan model disederhanakan; tubuh mempunyai umpan balik dan rentang pengaturan.','Tekanan berubah','Pembuluh & sinyal menyesuaikan','Filtrasi relatif dijaga'],
'l3-reabsorpsi':['Pengambilan kembali bersifat selektif','Zat berpindah dari lumen tubulus, melewati sel atau celah antarsel, lalu mencapai kapiler. Sebagian pengangkutan memerlukan energi; air bergerak mengikuti perbedaan osmotik. Reabsorpsi tidak berarti zat kembali ke glomerulus.','Pada kondisi normal, glukosa hampir seluruhnya kembali di proksimal. Urea tidak diperlakukan sama seperti glukosa.','Ke arah mana panah reabsorpsi harus digambar?','Dari filtrat dalam tubulus menuju darah di kapiler.','Filtrat dalam tubulus','Melintasi dinding tubulus','Kembali ke darah'],
'l3-sekresi':['Tambahan dari darah ke tubulus','Sekresi memindahkan zat dari kapiler ke lumen tubulus. Banyak zat asing disekresikan di proksimal; penanganan H+ dan K+ melibatkan segmen lebih lanjut. Sekresi membantu mengatur komposisi cairan, bukan sekadar membuang satu jenis sampah.','Jumlah zat dalam urin dapat lebih besar daripada jumlah yang masuk melalui filtrasi jika ada tambahan sekresi.','Apakah sekresi merupakan kebalikan arah reabsorpsi?','Ya, arah antarkompartemennya berlawanan, walaupun mekanisme pengangkutnya tidak selalu sama.','Zat di kapiler','Dipindah melewati dinding','Ditambahkan ke tubulus'],
'l3-proses':['Gunakan neraca zat','Untuk satu zat, jumlah yang dikeluarkan dapat diringkas sebagai tersaring − direabsorpsi + disekresikan. Neraca ini menghitung zat yang sama pada periode yang sama; jangan menjumlahkan gram glukosa dengan liter air.','Contoh satuan indeks: 100 masuk melalui filtrasi, 70 kembali, 10 ditambahkan; hasil akhir 40.','Mengapa tanda reabsorpsi negatif dan sekresi positif?','Reabsorpsi mengurangi zat dalam tubulus, sedangkan sekresi menambahnya.','100 tersaring','−70 kembali +10 ditambah','40 keluar (indeks)'],
'l3-jalur':['Setelah pemrosesan nefron','Cairan dari kolektivus mengalir ke saluran pengumpul ginjal, pelvis, ureter, kandung kemih, lalu uretra. Gerak otot saluran membantu mengalirkan urin; urin tidak hanya jatuh karena gravitasi.','Ureter membawa urin dari ginjal, sedangkan uretra membawa urin dari kandung kemih ke luar tubuh.','Apa kesalahan jika kedua saluran itu diberi label yang sama?','Arah dan organ yang dihubungkannya berbeda; istilah yang tertukar membuat jalur urin salah.','Kolektivus → pelvis','Ureter → kandung kemih','Uretra → luar tubuh'],
'l3-cairan':['Komposisi urin dapat berubah','Ketika tubuh perlu menghemat air, reabsorpsi air dapat meningkat sehingga volume urin turun dan zat terlarut lebih terkonsentrasi. Volume dan kepekatan berkaitan, tetapi juga dipengaruhi jumlah zat terlarut yang dikeluarkan.','Bandingkan kondisi normal dan setelah berkeringat pada model dengan kadar glukosa tetap. Ubah satu variabel agar sebab-akibat lebih mudah dibaca.','Mengapa sebaiknya tidak mengubah semua slider sekaligus?','Sulit menentukan perubahan hasil disebabkan oleh variabel yang mana.','Kebutuhan mempertahankan air','Reabsorpsi air berubah','Volume & kepekatan berubah'],
'l3-protein':['Temuan urin perlu konteks','Sel darah dan protein besar biasanya dipertahankan oleh penghalang yang sehat. Namun, penampakan urin tidak cukup untuk mengetahui zat tertentu. Hasil pemeriksaan perlu ditafsirkan bersama kondisi seseorang dan pemeriksaan lain.','Busa atau warna saja bukan bukti pasti adanya kerusakan glomerulus. Pengamatan dapat menjadi alasan bertanya, bukan membuat diagnosis.','Apa langkah berpikir yang lebih tepat daripada menebak penyakit dari warna?','Catat pengamatan dan minta bantuan orang dewasa atau tenaga kesehatan untuk penilaian yang sesuai.','Pengamatan atau hasil tes','Perlu konteks & pemeriksaan','Hindari diagnosis sendiri'],
'l3-lokasi':['Segmen mempunyai peran berbeda','Proksimal mengambil kembali banyak zat. Henle turun mudah dilalui air; bagian naik memindahkan garam dan relatif tidak dilalui air. Distal dan kolektivus menyetel komposisi akhir sesuai sinyal tubuh.','Perbedaan sifat kedua lengan Henle membantu membentuk kondisi medula yang mendukung pemekatan urin.','Mengapa tidak tepat menggambar air keluar sama banyak dari kedua lengan Henle?','Sifat permeabilitas dan proses pengangkutannya berbeda.','Proksimal: ambil kembali','Henle: air & garam berbeda','Distal/kolektivus: setel akhir'],
'l3-180':['Perhitungan pengembalian air','Ambil contoh ilustratif dewasa: 180 L filtrat dan 1,5 L urin sehari. Air yang kembali sekitar 178,5 L. Persentase yang kembali adalah 178,5 ÷ 180 × 100%, sekitar 99,2%. Nilai ini bukan target bagi setiap siswa.','Volume filtrat besar tidak berarti tubuh kehilangan volume itu. Perhatikan pembilang, penyebut, dan satuan sebelum menyimpulkan.','Jika urin dalam contoh menjadi 2 L, apakah seluruh filtrat bertambah?','Belum tentu. Perubahan reabsorpsi dapat mengubah urin meskipun filtrasi sama.','180 L filtrat (contoh)','178,5 L kembali ke darah','1,5 L menjadi urin'],
'l3-kasus':['Latih prediksi dengan alasan','Prediksi yang baik menyebutkan perubahan, proses yang menjadi penghubung, dan hasil yang diharapkan. Sesudah mengamati, bandingkan hasil dengan dugaan, termasuk kemungkinan bahwa model menyederhanakan tubuh nyata.','Setelah berkeringat: kehilangan air meningkat → sinyal penghematan air lebih kuat → reabsorpsi meningkat → urin cenderung lebih sedikit.','Jika hasil berbeda dari prediksi, apakah percobaan selalu gagal?','Tidak. Perbedaan dapat membantu memperbaiki alasan atau memeriksa variabel lain.','Nyatakan perubahan','Jelaskan proses penghubung','Bandingkan prediksi & hasil'],
'l3-glukosa':['Kapasitas pengangkut ada batasnya','Beban glukosa tersaring bergantung pada kadar darah dan laju filtrasi. Saat beban melewati kapasitas pengangkut, kelebihannya tetap dalam filtrat. Model memakai batas tegas untuk belajar; tubuh nyata memiliki transisi yang lebih bertahap.','Pada model GFR 100%: beban 300, kapasitas 180, sehingga sisa 120 unit indeks ke urin. Indeks ini bukan gram glukosa nyata.','Mengapa grafik harus menyebutkan GFR yang dipakai?','Kadar darah yang sama dapat menghasilkan beban tersaring berbeda bila laju filtrasi berbeda.','Beban glukosa tersaring','Kapasitas reabsorpsi terbatas','Kelebihan tersisa di urin'],
'l3-adh':['Sinyal mengatur permeabilitas air','ADH dibuat di hipotalamus dan dilepas dari hipofisis posterior. ADH meningkatkan kemampuan segmen akhir, terutama kolektivus, untuk melewatkan air melalui aquaporin. Air kemudian mengikuti gradien osmotik menuju jaringan dan darah.','ADH bukan air tambahan dan bukan pompa yang mendorong semua zat. Pengaruh utamanya dalam model adalah perubahan reabsorpsi air.','Apa hubungan ADH lebih kuat dengan volume urin, bila faktor lain sama?','Lebih banyak air kembali sehingga volume urin cenderung lebih kecil.','Sinyal ADH meningkat','Permeabilitas air meningkat','Air kembali; urin berkurang'],
'l3-warna':['Indikator bukan diagnosis','Kepekatan pigmen dapat mengubah warna urin, tetapi makanan, obat, dan kondisi lain juga berpengaruh. Volume, warna, dan bau perlu konteks. Satu pengamatan tidak dapat menentukan fungsi ginjal secara lengkap.','Warna lebih pekat pada ilustrasi berarti perbandingan pigmen terhadap air lebih besar, bukan otomatis menunjukkan satu penyakit tertentu.','Apakah urin bening selalu membuktikan ginjal sehat?','Tidak. Penilaian kesehatan memerlukan konteks dan pemeriksaan yang sesuai.','Amati ciri urin','Pertimbangkan banyak penyebab','Tanyakan bila perlu'],
'l4-batu':['Kristal dapat membesar','Sebagian zat dalam urin dapat mengkristal dan membentuk batu. Jenis batu serta faktor penyebabnya beragam. Masalah dapat timbul ketika batu menghambat aliran atau menimbulkan iritasi; ukuran dan lokasi juga memengaruhi akibatnya.','Batu tidak sama dengan endapan semua jenis makanan. Pencegahan dan penanganannya bergantung pada penilaian kesehatan.','Mengapa posisi batu penting selain ukurannya?','Batu di saluran yang sempit dapat menghambat aliran urin.','Zat mengkristal','Kristal dapat membentuk batu','Lokasi memengaruhi aliran'],
'l4-nefritis':['Peradangan berbeda dari sumbatan','Peradangan dapat melibatkan bagian ginjal yang berbeda dan memiliki beragam penyebab. Bila struktur penyaring terganggu, perpindahan zat dapat berubah. Istilah nefritis tidak berarti semua kasus mempunyai penyebab atau pengobatan yang sama.','Bandingkan mekanisme: batu dapat menghalangi aliran; peradangan dapat mengganggu jaringan. Keduanya tidak boleh disamakan hanya karena sama-sama berkaitan dengan ginjal.','Mengapa nama organ saja belum cukup menentukan terapi?','Penyebab, bagian yang terkena, dan tingkat gangguan harus dinilai terlebih dahulu.','Pemicu peradangan','Jaringan ginjal terganggu','Fungsi dapat berubah'],
'l4-pgk':['Perubahan menetap perlu pemantauan','Penyakit ginjal kronis berkaitan dengan kelainan struktur atau fungsi yang berlangsung setidaknya tiga bulan. Penilaian menggunakan pemeriksaan, bukan hanya ada atau tidaknya keluhan. Orang dapat belum menyadari gangguan pada tahap awal.','Tidak merasa nyeri bukan jaminan seluruh ukuran fungsi ginjal normal. Pemeriksaan dipilih sesuai faktor risiko oleh tenaga kesehatan.','Mengapa disebut kronis dan bukan sekadar hasil satu hari?','Istilah tersebut mencakup sifat gangguan yang menetap dalam waktu lama.','Kelainan struktur/fungsi','Menetap setidaknya 3 bulan','Perlu penilaian & pemantauan'],
'l4-dialisis-dasar':['Membran membantu pertukaran','Pada hemodialisis, darah mengalir pada satu sisi membran dan cairan dialisis pada sisi lain. Perbedaan konsentrasi membantu pemindahan zat tertentu; pengaturan tekanan membantu pengeluaran cairan. Darah dan cairan dialisis tidak dicampur langsung.','Sel darah dipertahankan di jalur darah. Dialisis menggantikan sebagian tugas ginjal, bukan seluruh fungsi hormonalnya.','Mengapa gambar dua cairan harus dipisahkan membran?','Pertukaran berlangsung melewati membran, bukan dengan menuangkan keduanya menjadi satu.','Darah di satu sisi','Membran: pertukaran zat','Dialisat di sisi lain'],
'l4-risiko':['Risiko bukan kepastian','Faktor risiko meningkatkan kemungkinan gangguan; faktor itu tidak membuktikan bahwa seseorang pasti sakit. Riwayat keluarga, kondisi kesehatan, dan kebiasaan dapat berperan dengan cara berbeda. Upaya pencegahan berfokus pada hal yang dapat dikelola.','Membahas faktor risiko seorang tokoh kasus tidak berarti menilai teman sekelas atau meminta data kesehatan pribadinya.','Apa perbedaan pernyataan berisiko dan pasti menderita?','Berisiko menyatakan peluang, sedangkan diagnosis memerlukan bukti pemeriksaan.','Kenali faktor risiko','Kelola yang dapat diubah','Pantau sesuai kebutuhan'],
'l4-sehat':['Kebiasaan konsisten','Kebiasaan sehat mendukung tubuh secara keseluruhan: aktivitas fisik, pola makan seimbang, tidak merokok, serta penggunaan obat sesuai petunjuk. Kebutuhan cairan berbeda menurut aktivitas, lingkungan, usia, dan kondisi kesehatan.','Pilih kebiasaan yang realistis, misalnya membawa air minum dan memberi tahu orang dewasa bila merasa tidak sehat.','Mengapa target yang ekstrem kurang tepat?','Kebiasaan perlu aman, sesuai kebutuhan, dan dapat dipertahankan.','Pilih kebiasaan realistis','Lakukan secara konsisten','Tinjau bersama orang dewasa'],
'l4-tanda':['Minta bantuan berdasarkan konteks','Keluhan seperti perubahan buang air kecil atau nyeri dapat memiliki banyak penyebab. Siswa perlu memberi tahu orang dewasa, terutama bila keluhan berat atau disertai kondisi yang mengkhawatirkan. Materi ini tidak menentukan diagnosis dari satu gejala.','Informasi yang berguna meliputi apa yang berubah dan kapan mulai terjadi, tanpa mencoba obat sendiri.','Mengapa bertanya lebih tepat daripada memilih penyakit dari daftar?','Gejala saling tumpang tindih; pemeriksaan membantu membedakan penyebab.','Ada perubahan atau keluhan','Beritahu orang dewasa','Dapatkan bantuan yang sesuai'],
'l4-mitos':['Nilai klaim dan buktinya','Klaim kesehatan perlu diuji: siapa yang menyampaikan, apa buktinya, untuk siapa klaim berlaku, dan apakah ada kepentingan penjualan. Testimoni satu orang tidak dapat membuktikan bahwa suatu produk aman dan efektif bagi semua orang.','Klaim pasti menyembuhkan semua penyakit harus memicu pemeriksaan sumber, bukan langsung dipercaya.','Apakah banyak dibagikan berarti bukti ilmiahnya kuat?','Tidak. Popularitas dan mutu bukti adalah dua hal berbeda.','Baca klaim dengan teliti','Periksa bukti & kepentingan','Bandingkan sumber tepercaya'],
'l4-isk':['Lokasi infeksi berpengaruh','Infeksi saluran kemih dapat mengenai bagian saluran yang berbeda. Infeksi kandung kemih dan infeksi yang mencapai ginjal tidak sama lokasinya. Penyebab keluhan perlu dinilai; antibiotik tidak digunakan sembarangan atau dibagikan kepada orang lain.','Istilah saluran kemih mencakup beberapa organ, bukan hanya ginjal.','Mengapa mengetahui lokasi keluhan saja belum cukup untuk memilih obat?','Lokasi bukan satu-satunya informasi untuk memastikan penyebab dan penanganan.','Saluran kemih terdiri organ','Infeksi dapat berbeda lokasi','Penanganan perlu penilaian'],
'l4-obat':['Ginjal dan pembuangan obat','Ginjal membantu mengeluarkan sebagian obat atau hasil penguraiannya. Fungsi ginjal dapat memengaruhi lamanya zat berada di tubuh. Sebagian obat juga dapat memengaruhi ginjal, terutama pada keadaan tertentu. Penggunaan harus mengikuti petunjuk tenaga kesehatan.','Jangan mengubah dosis obat yang diresepkan hanya berdasarkan simulasi atau bacaan ini.','Mengapa obat milik orang lain belum tentu cocok?','Kebutuhan, dosis, kondisi tubuh, dan interaksi obat dapat berbeda.','Obat masuk tubuh','Diproses & dikeluarkan','Gunakan sesuai petunjuk'],
'l4-hipertensi-diabetes':['Hubungan antarsistem','Tekanan darah tinggi dan diabetes dapat meningkatkan risiko kerusakan ginjal. Gangguan ginjal juga dapat memengaruhi pengaturan tekanan darah. Hubungannya dapat berlangsung dua arah, sehingga pemantauan dan pengelolaan kondisi penting.','Pada diagram, arah hubungan harus dijelaskan; jangan menganggap setiap orang dengan satu kondisi otomatis mempunyai kondisi lain.','Mengapa satu panah sebab-akibat tidak selalu cukup?','Beberapa proses membentuk hubungan umpan balik antarsistem.','Kondisi pembuluh/metabolik','Dapat memengaruhi ginjal','Ginjal ikut mengatur tekanan'],
'l4-dialisis-transplantasi':['Pilihan pengganti fungsi','Hemodialisis menggunakan penyaring di luar tubuh; dialisis peritoneal menggunakan membran peritoneum dengan pengaturan cairan khusus. Transplantasi menempatkan ginjal donor. Pemilihan terapi dilakukan bersama tim kesehatan dan memerlukan tindak lanjut.','Transplantasi bukan alasan menghentikan semua perawatan; pemantauan dan obat tertentu tetap diperlukan.','Apakah semua pilihan bekerja dengan cara yang sama?','Tidak. Mekanisme dan kebutuhan perawatannya berbeda.','Fungsi ginjal sangat menurun','Pertimbangkan pilihan terapi','Tindak lanjut tetap diperlukan'],
'l4-hidrasi':['Kebutuhan tidak seragam','Tubuh memperoleh air dari minuman dan makanan serta kehilangan air melalui beberapa jalur. Kebutuhan berubah dengan aktivitas dan cuaca. Sebagian kondisi kesehatan memerlukan anjuran cairan khusus; target umum tidak menggantikan anjuran tersebut.','Pada kegiatan belajar, gunakan model untuk mengamati konsep. Jangan sengaja menahan minum atau minum berlebihan sebagai percobaan.','Mengapa anjuran satu angka untuk semua orang dapat menyesatkan?','Usia, ukuran tubuh, aktivitas, lingkungan, dan kondisi kesehatan berbeda.','Asupan & kehilangan air','Kebutuhan tiap orang berbeda','Sesuaikan secara aman'],
'l4-sumber':['Telusuri asal informasi','Periksa lembaga atau penulis, tanggal peninjauan, rujukan, dan tujuan halaman. Cocokkan klaim penting pada lebih dari satu sumber yang dapat dipertanggungjawabkan. Gambar yang menarik dan istilah rumit tidak otomatis menandakan bukti yang baik.','Bedakan halaman edukasi lembaga kesehatan dengan iklan produk yang memakai bahasa seolah ilmiah.','Mengapa tanggal peninjauan tetap perlu diperiksa?','Sebagian rekomendasi atau bukti dapat berubah, walaupun konsep dasar tetap sama.','Kenali penulis & lembaga','Periksa tanggal dan rujukan','Bandingkan isi sumber'],
'l4-kebiasaan':['Rencana dapat ditinjau','Rencana yang baik menyebut tindakan kecil, waktu atau pemicunya, dan cara menilai apakah terlaksana. Fokus pada proses yang dapat dikendalikan, bukan janji menjamin tidak akan pernah sakit. Libatkan orang dewasa untuk kebiasaan yang sesuai kebutuhanmu.','Contoh: menyiapkan botol minum sebelum berangkat dan mengecek kembali kebiasaan itu pada akhir pekan.','Apa bedanya niat umum dan rencana yang dapat dilakukan?','Rencana menyebut tindakan dan waktu yang jelas sehingga dapat ditinjau.','Pilih satu tindakan','Tentukan waktu/pemicu','Tinjau pelaksanaannya']
};
