 [[180,220],[385,425],[555,595]].forEach(([a,b])=>body+=arrow(a,127,b-8,127,'#b84d55'));
 body+=`<path d="M300 164V188H90V229" fill="none" stroke="#16786e" stroke-width="4" marker-end="url(#${id})"/>`+v11Txt(206,218,'Filtrasi',17,'#16786e',20);
 const ns=['Bowman','Proksimal','Henle','Distal','Kolektivus'];ns.forEach((n,i)=>{body+=box(25+i*158,235,130,64,n,'#def1ff');if(i<4)body+=arrow(155+i*158,267,176+i*158,267)});
