/* v11: generated individual icons, accessible visual tabs and image zoom. */
function v11Icon(name){return `<img class="v11-icon" src="${V11_ICONS[name]}" alt="" aria-hidden="true">`}
Object.assign(ICONS,{home:v11Icon('home'),material:v11Icon('material'),sim:v11Icon('simulation'),target:v11Icon('objectives'),game:v11Icon('game'),eval:v11Icon('evaluation'),result:v11Icon('results'),reflect:v11Icon('reflection'),help:v11Icon('help')});
const V11_LABS={lab1:['anatomy','Anatomi ginjal','Kenali organ, nefron, dan dua jalur cairan.'],lab2:['filtration','Filtrasi','Selidiki zat yang lolos dari darah ke filtrat.'],lab3:['transport','Reabsorpsi & sekresi','Ikuti zat yang kembali dan ditambahkan ke tubulus.'],lab4:['health','Ginjal & kesehatan','Hubungkan fungsi ginjal dengan kebiasaan sehari-hari.']};
renderMaterialHub=function(){setApp(`<section class="v11-material"><div class="v11-material-head"><div><div class="eyebrow">JELAJAHI · PAHAMI · TERAPKAN</div><h1>Empat stasiun, satu perjalanan</h1><p>Pilih topik. Baca materi, jelajahi diagram, lalu cek pemahamanmu.</p></div>${v11Icon('material')}</div><div class="v11-stations">${Object.entries(LABS).map(([id,lab],i)=>{const [icon,title,desc]=V11_LABS[id],p=labCoreProgress(id),done=state.labs[id].checkpoint.status==='benar';return `<article class="v11-station"><div class="v11-station-top">${v11Icon(icon)}<div><span class="eyebrow">STASIUN ${i+1}</span><h2>${title}</h2></div><span class="v11-status">${done?'✓ Tuntas':p.done?'Sedang dipelajari':'Siap dijelajahi'}</span></div><p>${desc}</p><div class="v11-station-bottom"><div><span>${p.done}/${p.total} materi inti dibuka</span><progress value="${p.done}" max="${p.total}" aria-label="Materi inti dibuka: ${title}"></progress><small>${lab.slides.length-p.total} topik pendalaman tersedia</small></div><button class="btn primary" onclick="labNav('${id}',${labResumeIndex(id)})" aria-label="${p.done?'Lanjutkan':'Mulai'} ${title}">${p.done?'Lanjutkan':'Mulai'} ${v11Icon('next')}</button></div></article>`}).join('')}</div><div class="actions split"><button class="btn" onclick="home()">${v11Icon('home')} Menu utama</button><span class="muted">Bebas memilih urutan · Progres tersimpan di perangkat ini</span></div></section>`)};
// Remove old unlabeled/inaccurate miniature diagrams from the text reading pane.
for(const lab of Object.values(LABS))for(const slide of lab.slides){slide.html=slide.html.replace(/<div class="lab-inline-svg-wrap"[^>]*>[\s\S]*?<\/svg>\s*<\/div>/g,'<p class="v11-visual-link"><button class="btn" onclick="v8ReadTab(\'visual\')">Buka diagram berlabel</button></p>')}
const v11OldLab=renderLab;
renderLab=function(id,idx){v11OldLab(id,idx);const screen=document.querySelector('.lab-reader-screen'),visual=document.querySelector('.lab-reader-visual'),content=document.querySelector('.lab-reader-content');if(!screen||!visual)return;screen.classList.add('v11-reader');const slide=LABS[id].slides[Math.max(0,Math.min(Number(idx)||0,LABS[id].slides.length-1))];const original=visual.querySelector('figure');visual.innerHTML=v11Diagram(slide);if(original){const detail=document.createElement('details');detail.className='v11-reference';detail.innerHTML='<summary>Opsi gambar / ilustrasi pendukung</summary>';detail.append(original);visual.append(detail)}visual.id='v11VisualPanel';content.id='v11TextPanel';document.getElementById('v8VisualTab').setAttribute('aria-controls',visual.id);document.getElementById('v8TextTab').setAttribute('aria-controls',content.id);document.getElementById('v8VisualTab').innerHTML=v11Icon('anatomy')+' Gambar / diagram';document.getElementById('v8TextTab').innerHTML=v11Icon('material')+' Materi';visual.querySelector('figcaption span').innerHTML=`<button class="btn v11-zoom-trigger" onclick="v11Zoom(this.closest('figure').querySelector('svg'))">${v11Icon('zoom')} Perbesar diagram</button>`;v8ReadTab('text');v11Enhance(screen);};
v8ReadTab=function(t){const content=document.querySelector('.lab-reader-content'),visual=document.querySelector('.lab-reader-visual');if(!content||!visual)return;V8_VIEW.labTab=t;content.hidden=t==='visual';visual.hidden=t==='text'&&innerWidth<1000;document.querySelector('.lab-reader-grid').classList.toggle('v11-visual-only',t==='visual');document.getElementById('v8TextTab').setAttribute('aria-pressed',String(t==='text'));document.getElementById('v8VisualTab').setAttribute('aria-pressed',String(t==='visual'));};
const v11OldReadPage=v8ReadPage;
v8ReadPage=function(d){v11OldReadPage(d);v11Enhance(document.getElementById('v8ReaderBody'));};
function v11Enhance(root=document){if(!root)return;root.querySelectorAll('button').forEach(b=>{if(b.querySelector('.v11-icon')||b.classList.contains('dot')||b.closest('#simSvg,.v11-zoom-dialog'))return;const action=b.getAttribute('onclick')||'',label=b.textContent.trim();let key=null;
 if(/exitApplication/.test(action))key='exit';else if(/closeModal|simUiCloseZoom/.test(action))key='close';else if(/navigate\('opening/.test(action))key='home';else if(/home\(\)/.test(action))key='home';else if(/help\(/.test(action))key='help';else if(/navigate\('materialHub/.test(action))key='material';else if(/navigate\('simulation|labTrySim/.test(action))key='simulation';else if(/navigate\('game/.test(action))key='game';else if(/navigate\('results/.test(action))key='results';else if(/navigate\('evaluation/.test(action))key='evaluation';else if(/navigate\('reflection/.test(action))key='reflection';else if(/navigate\('objectives/.test(action))key='objectives';else if(/navigate\('guide/.test(action))key='help';else if(/Sebelum|Kembali|←/.test(label)||/v8ReadPage\(-1/.test(action))key='back';else if(/Lanjut|berikut|Bagian|Mulai|Buka|Masuk|Cek Pemahaman/.test(label)&&!/arcade|simUi|v9Picture/.test(action))key='next';
 if(key){if(key==='help'&&label==='?')b.innerHTML='<span>Petunjuk</span>';for(const node of [...b.childNodes])if(node.nodeType===3)node.textContent=node.textContent.replace(/[←→⌂⏻]/g,'').trim();b.insertAdjacentHTML('afterbegin',v11Icon(key));b.classList.add('v11-nav-button')}
 });root.querySelectorAll('img:not(.v11-icon):not(.mascot-img),svg.v11-diagram,svg.lab-inline-svg').forEach(el=>{if(el.closest('button,.brand,.v8-cover,.v8-welcome,.v8-hub-head,.arcade-card-art,.mobile-nav,.v11-zoom-dialog,#v11ZoomCanvas')||el.classList.contains('v8-rbc-icon')||el.onclick||el.dataset.v11Zoom)return;el.dataset.v11Zoom='true';el.classList.add('v11-zoomable');el.setAttribute('tabindex','0');el.setAttribute('role','button');el.setAttribute('aria-label','Perbesar: '+(el.getAttribute('alt')||el.getAttribute('aria-label')||'ilustrasi'));el.addEventListener('click',()=>v11Zoom(el));el.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();v11Zoom(el)}})});}
const v11OldSetApp=setApp;
setApp=function(html){v11OldSetApp(html);v11Enhance(document.getElementById('app'))};
const v11OldShowModal=showModal;
showModal=function(title,body,buttons){v11OldShowModal(title,body,buttons);v11Enhance(document.getElementById('modalRoot'))};
let v11ZoomScale=1;
function v11Zoom(el){if(!el)return;const name=el.getAttribute('alt')||el.querySelector('title')?.textContent||'Ilustrasi';const clone=el.cloneNode(true);clone.removeAttribute('onclick');clone.removeAttribute('onkeydown');clone.removeAttribute('tabindex');clone.removeAttribute('id');clone.removeAttribute('role');clone.removeAttribute('data-v11-zoom');clone.classList.remove('v11-zoomable');if(el.tagName.toLowerCase()==='img')clone.src=el.currentSrc||el.src;showModal('Jelajahi gambar',`<div class="v11-zoom-toolbar"><span>${esc(name)}</span><button class="btn" id="v11ZoomMinus" aria-label="Perkecil gambar" onclick="v11Scale(-.25)">−</button><output id="v11ZoomLevel">100%</output><button class="btn" id="v11ZoomPlus" aria-label="Perbesar gambar" onclick="v11Scale(.25)">+</button><button class="btn" onclick="v11Scale(0)">Pas layar</button></div><div class="v11-zoom-viewport" id="v11ZoomViewport"><div id="v11ZoomCanvas">${clone.outerHTML}</div></div><p class="v11-zoom-note">Perbesar dengan +, lalu gulir untuk menjelajahi gambar. Esc untuk menutup.</p>`);document.querySelector('#modalRoot .modal').classList.add('v11-zoom-dialog');v11ZoomScale=1;v11Scale(0);}
function v11Scale(delta){v11ZoomScale=delta===0?1:Math.max(.5,Math.min(3,v11ZoomScale+delta));const c=document.getElementById('v11ZoomCanvas');if(!c)return;c.style.width=(v11ZoomScale*100)+'%';const im=c.querySelector('img');if(im)im.style.height=(58*v11ZoomScale)+'dvh';document.getElementById('v11ZoomLevel').textContent=Math.round(v11ZoomScale*100)+'%';document.getElementById('v11ZoomMinus').disabled=v11ZoomScale<=.5;document.getElementById('v11ZoomPlus').disabled=v11ZoomScale>=3;}
simUiZoomImage=v11Zoom;
