const V13_ASSETS={"student_boy": "assets/images/student_boy.webp", "student_girl": "assets/images/student_girl.webp", "nefi_anime": "assets/images/nefi_anime.webp", "cinematic_lab": "assets/images/cinematic_lab.webp"};
