const V13_GUESSES=['Ginjal dapat menyesuaikan banyaknya air yang dipertahankan tubuh','Ginjal berhenti bekerja ketika kita berkeringat','Semua cairan yang diminum langsung menjadi urin','Saya belum yakin'];
function v13Step(){return Math.max(0,Math.min(V13_STORY.length-1,Number(state.onboarding.cinemaStep)||0))}
function v13Sprite(who,active){const c=V13_CAST[who];return `<div class="v13-actor ${who} ${active===who?'speaking':''}"><img class="mascot-img" src="${V13_ASSETS[c.asset]}" alt="${c.name}, ${c.role}"><span>${c.name}</span></div>`}
renderAperception=function(){const i=v13Step(),[who,line,prompt]=V13_STORY[i],c=V13_CAST[who];setApp(`<section class="v13-cinema" aria-label="Dialog pembuka"><div class="v13-story-head"><div><span class="eyebrow">CERITA PEMBUKA · SEBUAH PENYELIDIKAN</span><h1>Misteri di balik setetes urin</h1></div><span class="badge">Adegan ${i+1} / ${V13_STORY.length}</span></div><div class="v13-stage" style="background-image:url('${V13_ASSETS.cinematic_lab}')">${v13Sprite('ari',who)}${v13Sprite('nefi',who)}${v13Sprite('naya',who)}<span class="v13-scene-label">Laboratorium IPA · setelah pelajaran olahraga</span></div><section class="v13-dialog" aria-labelledby="v13Speaker"><div class="v13-speaker"><strong id="v13Speaker">${c.name}</strong><span>${c.role}</span></div><p id="v13Speech" tabindex="-1">${line}</p>${prompt==='choice'?`<fieldset class="v13-prompt"><legend>Giliranmu · pilih dugaan awal</legend><div class="v13-choices">${V13_GUESSES.map((x,n)=>`<label><input type="radio" name="ap" value="${n}" onchange="v13Guess(${n})" ${state.onboarding.hydrationGuess===x?'checked':''}><span>${esc(x)}</span></label>`).join('')}</div><small>Tidak dinilai. Kita akan meninjau dugaan ini setelah belajar.</small></fieldset>`:prompt==='hypothesis'?`<div class="v13-prompt"><label for="hypothesis">Giliranmu · tulis dugaanmu tentang saringan ginjal</label><textarea id="hypothesis" maxlength="220" rows="2" oninput="v13Hypothesis(this.value)" placeholder="Menurutku, sel darah tetap di dalam darah karena…">${esc(state.onboarding.hypothesis||'')}</textarea><div class="v13-prompt-foot"><small>1–2 kalimat · tidak dinilai</small><button class="btn" onclick="v13Unsure()">Saya belum punya dugaan</button></div></div>`:''}<p class="v13-error" id="v13StoryError" role="status"></p><div class="v13-story-actions"><button class="btn" onclick="v13StoryMove(-1)" ${i===0?'disabled':''}>${v11Icon('back')} Sebelumnya</button><span>${prompt?'Simpan dugaan, lalu lanjutkan':'Ikuti percakapan sesuai ritmemu'}</span><button class="btn primary" onclick="v13StoryMove(1)">${i===V13_STORY.length-1?'Mulai penjelajahan':'Lanjutkan'} ${v11Icon('next')}</button></div></section></section>`)};
function v13Guess(n){if(!V13_GUESSES[n])return;state.onboarding.hydrationGuess=V13_GUESSES[n];saveState(false);document.getElementById('v13StoryError').textContent='Dugaan tersimpan.'}
function v13Hypothesis(value){state.onboarding.hypothesis=String(value).slice(0,220);saveState(false)}
function v13Unsure(){v13Hypothesis('Saya belum punya dugaan.');document.getElementById('hypothesis').value=state.onboarding.hypothesis;document.getElementById('v13StoryError').textContent='Tidak apa-apa. Mari cari petunjuk bersama.'}
function v13StoryMove(delta){const i=v13Step(),kind=V13_STORY[i][2];if(delta>0&&((kind==='choice'&&!state.onboarding.hydrationGuess)||(kind==='hypothesis'&&!state.onboarding.hypothesis?.trim()))){document.getElementById('v13StoryError').textContent='Isi dugaanmu atau pilih opsi belum yakin untuk melanjutkan.';return}if(delta>0&&i===V13_STORY.length-1){finishAperception();return}state.onboarding.cinemaStep=Math.max(0,Math.min(V13_STORY.length-1,i+delta));saveState(false);renderAperception();document.getElementById('v13Speech')?.focus()}
finishAperception=function(){if(!state.onboarding.hydrationGuess||!state.onboarding.hypothesis?.trim()){state.onboarding.cinemaStep=!state.onboarding.hydrationGuess?3:7;renderAperception();return}Object.assign(state.onboarding,{aperceptionCompleted:true,completed:true,cinemaStep:10});saveState(false);navigate('dashboard')};
