const v13Lab=renderLab;renderLab=function(id,idx){v13Lab(id,idx);const lab=LABS[id],grid=document.querySelector('.lab-reader-grid');if(!lab||!grid)return;idx=Math.max(0,Math.min(Number(idx)||0,lab.slides.length-1));document.querySelector('.v8-lab-map')?.remove();const slide=lab.slides[idx],subtitle=V11_DEPTH[slide.id]?.[0]||lab.subtitle||'Jelajahi konsep dan diagram.';grid.insertAdjacentHTML('beforebegin',`<details class="v13-topic-map" id="v13TopicMap" ontoggle="v13MapState(this.open)"><summary>Pilih topik · ${esc(slide.title)}</summary><div><label for="v13TopicSelect">Peta materi — ${esc(V11_LABS[id][1])}</label><select id="v13TopicSelect" onchange="v13SelectTopic(this.value)">${['inti','pendalaman'].map(level=>`<optgroup label="${level==='inti'?'Materi inti':'Pendalaman'}">${lab.slides.map((s,n)=>({s,n})).filter(({s})=>(s.level==='inti'?'inti':'pendalaman')===level).map(({s,n})=>`<option value="${n}" ${n===idx?'selected':''}>${n+1}. ${esc(s.title)} — ${esc(V11_DEPTH[s.id]?.[0]||'Jelajahi konsep dan diagram')}</option>`).join('')}</optgroup>`).join('')}</select><p class="v13-topic-subtitle">${esc(subtitle)}</p></div></details>`);const button=document.querySelector('[onclick="v8LabMap()"]');if(button){button.setAttribute('aria-controls','v13TopicMap');button.setAttribute('aria-expanded','false')}};
